-- ============================================================
-- Content Seed — HİSSƏ 7/13: DB kontentinin ru/tr tərcümələri
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Hissələri istənilən ardıcıllıqla, istənilən qədər təkrar işlətmək təhlükəsizdir.
-- Cəmi: 12258 UPDATE, 13 hissə
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Эндокринная система вашего малыша уже готова обеспечивать работу всего организма и помогать ему адаптироваться к внешнему миру после 9 месяцев, проведённых в защищённой среде матки. Один из вырабатываемых гормонов — кортизол, который активно участвует в обмене углеводов и вызывает в организме определённую стрессовую реакцию. Кортизол — это стероидный гормон, который синтезируется надпочечниками малыша и поступает в кровь. Выработка этого гормона помогает организму малыша справляться с напряжением. Умеренный стресс, создаваемый кортизолом, способствует укреплению сердца, мышц и мозга малыша. Благодаря этому после рождения ему потребуется меньше помощи для адаптации и поддержания жизненно важных функций.;;;
Кортизол, особенно активно выделяющийся во время родов, также стимулирует выработку адреналина — ещё одного гормона, связанного со стрессом. Адреналин придаёт малышу энергию и повышает его активность. Эта энергия помогает ему адаптироваться к новой среде во время родов и в первые часы после встречи с внешним миром.'), baby_message_ru = COALESCE(baby_message_ru, 'Мой чемодан уже собран! 🧳 Я полностью готов. Мои лёгкие готовы сделать первый вдох, а желудок — принять грудное молоко. Я просто жду, когда «откроется дверь». Может быть, вам стоит немного прогуляться? Это поможет мне найти дорогу.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если роды ещё не начались, вы можете чувствовать сильную усталость. Бессонные ночи, вызванные стрессом и тревогой, способны ещё больше её усилить. Если на этом этапе из сосков выделяется молозиво, это связано с действием гормонов, подготавливающих грудь к кормлению.;;;
Если роды не начинаются после завершения 40 недель беременности, у малыша может развиться синдром аспирации мекония. Меконий — это первый стул малыша, который накапливается в его кишечнике и в норме отходит в течение первых 24 часов после рождения. Однако из-за стресса или нехватки кислорода он может выделиться ещё до рождения. Опасность возникает, если малыш вдыхает меконий и тот попадает в лёгкие. Меконий имеет густую и липкую консистенцию, поэтому при попадании в лёгкие может нарушить дыхание. Это состояние называется синдромом аспирации мекония. При выделении мекония околоплодные воды приобретают зеленоватый оттенок. Поэтому внимательно следите за выделениями и, если заметите значительное уменьшение движений малыша, немедленно обратитесь в ближайшее медицинское учреждение.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Попросите супруга или кого-нибудь из близких сделать вам лёгкий массаж плеч. Расслабление от прикосновений повысит уровень окситоцина (гормона любви) в организме и поможет облегчить роды.') WHERE id = 'acaaba70-7d7b-40eb-88be-941234cfb162';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Из-за перенашивания беременности плацента может начать стареть. Это не представляет проблемы, пока малыш получает достаточно кислорода и продолжает набирать вес. Плацента — это орган, который на протяжении всей беременности обеспечивает обмен веществ между вашим организмом и малышом. Она формируется и развивается на очень раннем этапе после оплодотворения, а вскоре после рождения малыша отделяется от матки и выходит наружу. После родов плацента весит примерно 500 грамм, имеет диаметр 20-25 см и толщину 2-3 см, а по форме напоминает плоский диск. Старение плаценты, особенно после 36-й недели беременности, считается нормальным процессом. На самом деле состояние, известное как старение плаценты, представляет собой отложение солей кальция в её тканях.'), baby_message_ru = COALESCE(baby_message_ru, 'Может быть, нам нужна помощь? 🩺 Возможно, врачи уже обсуждают стимуляцию родов (индукцию). Не бойтесь. Я хочу появиться на свет, просто иногда природе нужен небольшой толчок. Неважно, каким образом я приду в этот мир, главное — мы наконец встретимся.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'С началом второго триместра беременности у вас могла появиться одышка. В третьем триместре она обычно становится значительно сильнее. Из-за смещения диафрагмы вверх лёгкие оказываются сдавленными. Доступное им пространство уменьшается, поэтому они вмещают меньше воздуха. В результате дышать может стать довольно трудно и возникает ощущение «нехватки воздуха».;;;
Затруднённое дыхание, с которым во время беременности сталкивается почти каждая женщина, можно значительно уменьшить с помощью дыхательных упражнений, укрепляющих диафрагму. Кроме того, регулярные дыхательные упражнения помогают увеличить объём лёгких и улучшить поступление кислорода к малышу.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Если сегодня вы почувствуете схватки, не бойтесь. Каждая схватка — это «волна», которая приближает вас к малышу ещё на один шаг. Уверенно двигайтесь вместе с этой волной и не поддавайтесь страху.') WHERE id = '39da3e28-3bb4-466f-a4b2-49f4aa6296da';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Хотя на этой неделе беременности срок, необходимый для начала родов, уже полностью завершён, некоторые физиологические особенности могут препятствовать их началу, в результате чего роды могут запаздывать. Однако всё это время ваш малыш продолжает расти и развиваться. Если малыш родится на 42-й неделе беременности, вы можете заметить, что его волосы и ногти довольно длинные. Кроме того, поскольку такие малыши рождаются на 2-3 недели позже своих сверстников, их глаза обычно открыты, а сами они более бодрые. Все их рефлексы, особенно сосательный, развиты лучше, чем у других новорождённых, поэтому они более активны. Тем не менее из-за рисков, связанных с 42-й неделей беременности, врач может попросить вас приходить на осмотр не реже одного раза в 2 дня, чтобы внимательнее следить за состоянием малыша. Обследование на 42-й неделе беременности проводится для оценки состояния малыша на основании таких показателей, как результаты УЗИ, КТГ, подсчёт шевелений и объём амниотической жидкости.'), baby_message_ru = COALESCE(baby_message_ru, 'Я чувствую тебя... ❤️ Я знаю, что твоё терпение почти на исходе. У меня болит спинка, а у тебя отекли ноги. Осталось совсем немного, Anacan, обещаю. Когда ты возьмёшь меня на руки, все эти трудности забудутся. Ты самая сильная женщина в мире!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если родовые схватки не начинаются естественным образом, врач может провести кесарево сечение, поскольку некоторые проблемы со стороны вашего организма или малыша могут привести к осложнениям при естественных родах.;;;
Если во время сокращений матки из-за недостатка кислорода у малыша снижается частота сердцебиения, плацента перекрывает шейку матки, положение малыша не подходит для естественных родов, часть пуповины выпадает через шейку матки либо имеются препятствующие естественным родам проблемы, такие как миома в области шейки матки, генитальный герпес или инфекция, родоразрешение проводится методом кесарева сечения.;;;
При наличии этих проблем также нельзя использовать искусственную стимуляцию схваток синтетическим аналогом окситоцина — гормона, который вырабатывается гипофизом, расположенным в передней части головного мозга, и запускает родовые схватки.;;;
Если вам предстоит кесарево сечение, сначала анестезиолог вводит вас в общий наркоз или проводит регионарную анестезию. После последовательного рассечения в 7 этапов кожи, подкожной клетчатки, фасции, передней брюшной стенки, наружной брюшины, внутренней брюшины и мышц матки врач получает доступ к амниотическому мешку, в котором находится малыш.;;;
Врач вскрывает этот мешок и извлекает малыша. После пересечения пуповины и передачи малыша извлекают плаценту и очищают полость матки. На заключительном этапе 7 рассечённых слоёв аккуратно и эстетично ушивают, после чего операция кесарева сечения завершается.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Почаще повторяйте себе: "Я готова, моё тело готово, мой малыш готов". Позитивные установки повышают болевой порог и помогают более благоприятно пройти через процесс родов.') WHERE id = '3c9f9854-9405-4f6e-90ed-de351c308dea';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'На 42-й неделе беременности покрывающий тело малыша светло-жёлтый слой первородной смазки, вероятнее всего, уже начал впитываться в кожу. Первородная смазка — это тонкий защитный слой, который начинает вырабатываться в третьем триместре беременности, на 80% состоит из воды и содержит большое количество липидов и белков. Распределение первородной смазки по поверхности кожи зависит от срока беременности, способа родоразрешения и массы тела малыша. В состав первородной смазки входят лизоцим, способный уничтожать микроорганизмы, а также защитные клетки, противодействующие одному из видов бактерий, которые могут повреждать лёгкие и вызывать воспаление. Кроме того, этот кремообразный слой содержит около 40 различных белков, поддерживающих врождённый иммунитет малыша.;;;
Однако из-за переношенной беременности значительная часть этого слоя впитывается в кожу ещё до рождения. После впитывания первородной смазки кожа малыша на этом этапе может стать немного сухой. Из-за сухости и уменьшения объёма амниотической жидкости на некоторых участках кожа может шелушиться и отслаиваться.'), baby_message_ru = COALESCE(baby_message_ru, 'Я жду главного сигнала! 🚦 В твоём организме повышается уровень гормона родов (окситоцина). А я давлю головкой вниз. Схватки могут начаться в любой момент. Твоя сумка уже у двери? Думаю, время ехать в роддом приближается.'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'Если на этом этапе у вас нет проблем, требующих кесарева сечения, врач может предложить начать роды с помощью искусственной стимуляции схваток. При нормальном течении беременности ближе к последним неделям гормон окситоцин, выделяемый гипофизом головного мозга, воздействует на мышцы матки и вызывает их сокращения. Эти сокращения приводят к постепенному раскрытию шейки матки. Когда шейка матки раскрывается полностью, начинается основной этап родов, и малыш проходит через родовые пути. Однако по некоторым неизвестным причинам окситоцин может не вырабатываться в головном мозге, из-за чего родовые схватки не начинаются.;;;
Искусственная стимуляция схваток — это медикаментозное начало естественных родов в случаях, когда по определённым причинам они не начинаются самостоятельно. Препарат, применяемый для искусственной стимуляции, содержит гормон окситоцин, который вызывает сокращения мышц матки и тем самым запускает роды. Эта процедура, называемая "индукцией родов", применяется, чтобы доношенный малыш, который всё ещё находится в утробе матери, появился на свет естественным (вагинальным) путём. Если схватки уже начались, но раскрытие шейки матки происходит недостаточно быстро, врач также может применить этот метод для ускорения родов.'), daily_tip_ru = COALESCE(daily_tip_ru, 'Вы уже подошли к концу этого пути и началу долгожданной встречи. Сегодня просто отдохните. Пусть все ваши молитвы и желания будут о малыше. Осталось совсем немного — всего несколько часов до того момента, когда вы почувствуете этот чудесный аромат.') WHERE id = '9ac98c98-32af-413c-ad09-92ec7b838b44';
UPDATE public.pregnancy_daily_content SET baby_development_ru = COALESCE(baby_development_ru, 'Если до этого момента роды ещё не произошли, то начиная с сегодняшнего дня вы наконец встретитесь со своим малышом. 😊 Существуют определённые признаки, которые однозначно указывают на начало родов. Если вы заметите хотя бы один из них, следует незамедлительно связаться с врачом. Структура, называемая "слизистой пробкой" или "предвестником родов", в течение всей беременности защищает шейку матки от вредных микроорганизмов и помогает сохранять стерильность амниотической жидкости. Она может отойти как за несколько недель, так и за несколько часов до родов. Появление этих густых слизистых выделений с примесью крови свидетельствует о том, что шейка матки готовится к родам.;;;
Регулярные схватки, интенсивность которых постепенно нарастает, — наиболее очевидный признак начала родов. Они сильнее ложных схваток и способствуют быстрому раскрытию шейки матки.;;;
При излитии амниотической жидкости (вод) необходимо незамедлительно обратиться к врачу. Жидкость может излиться как сильным потоком, так и понемногу подтекать. Излитие амниотической жидкости указывает на то, что до родов остались считаные часы. 😊'), baby_message_ru = COALESCE(baby_message_ru, 'Последние 24 часа? ⏳ До завершения 42-й недели осталось совсем немного. По медицинским показаниям нам уже непременно нужно встретиться. Я тоже скучаю. Мне не терпится перейти из тёмного мира в твой светлый мир. Готовься, скоро увидимся!'), baby_size_fruit_ru = COALESCE(baby_size_fruit_ru, 'Большой арбуз'), body_changes_ru = COALESCE(body_changes_ru, 'К концу 42-й недели роды уже должны состояться. После долгого и утомительного 9-месячного приключения вы наконец встретились со своим малышом. 😊 От имени семьи Anacan поздравляем вас и вашего супруга и желаем вам долгой, здоровой и счастливой жизни вместе с малышом. Благодарим за поддержку, которую вы оказывали нам всё это время. До встречи в модуле "Мама" нашего приложения!'), daily_tip_ru = COALESCE(daily_tip_ru, 'Сегодня день, когда происходит чудо. Как только вы возьмёте малыша на руки, вся усталость исчезнет. А сейчас сделайте глубокий вдох и насладитесь этим историческим моментом. Вы справились!') WHERE id = '67f8b3d3-cbfc-4995-af5b-fd9e49e105ef';

-- ── blog_posts → ru (57 sətir) ──
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Отпуск по беременности и родам (декрет): кому положен и как рассчитывается выплата?'), excerpt_ru = COALESCE(excerpt_ru, 'Сколько дней длится отпуск по беременности и родам (декрет) в Азербайджане? Кто может получить оплачиваемый декретный отпуск? Юридическое руководство о 126-дневном отпуске, формуле расчёта выплаты и сохранении рабочего места.'), content_ru = COALESCE(content_ru, '<p>Каждая работающая женщина, испытывающая радость беременности, в то же время беспокоится о своём будущем материальном положении. <em>"Когда мне нужно уйти с работы?", "Сколько денег мне положено?", "Сохранится ли за мной рабочее место?"</em>.</p><p><strong>Отпуск по беременности и родам</strong>, известный в народе как "декрет", на самом деле является законным правом каждой работающей мамы. Этот период защищён государством, чтобы вы могли отдохнуть и спокойно провести первые месяцы со своим малышом.</p><p>В этой статье мы отложим в сторону сложный язык законодательства и простыми словами расскажем о ваших правах и сумме, которую вы можете получить.</p><h2>Кому положен декретный отпуск?</h2><p>Главное условие для получения отпуска по беременности и родам и соответствующей выплаты — <strong>официальное трудоустройство</strong> и уплата взносов социального страхования (DSMF).</p><ul><li><p><strong>Кто может получить:</strong> Женщины, работающие по официальному трудовому договору (как в государственном, так и в частном секторе).</p></li><li><p><strong>Кто не может получить:</strong> Женщины, работающие неофициально, домохозяйки, а также лица, ведущие деятельность по VÖEN, но не уплачивающие взносы социального страхования.</p></li><li><p></p></li></ul><p></p><blockquote><p>Примечание: Если вы не работаете, выплата по беременности и родам вам не положена, однако единовременное пособие в размере 600 манатов предоставляется всем (независимо от того, работают они или нет).</p></blockquote><p>&gt;</p><h2>Сколько дней вы можете отдыхать? (Продолжительность)</h2><p>Согласно Трудовому кодексу Азербайджанской Республики, отпуск по беременности и родам предоставляется в общей сложности на <strong>126 календарных дней</strong>:</p><ul><li><p><strong>До родов:</strong> 70 дней (начиная примерно с 30-й недели беременности).</p></li><li><p><strong>После родов:</strong> 56 дней.</p></li></ul><p><strong>Исключения:</strong></p><ul><li><p><strong>Осложнённые роды (кесарево сечение) или двойня:</strong> Если роды прошли с осложнениями (например, было проведено кесарево сечение) либо родились двое или более детей, послеродовой отпуск продлевается до <strong>70 дней</strong> (всего 140 дней).</p></li></ul><h2>Как рассчитывается выплата по беременности и родам?</h2><p>Самый интересующий вопрос: "Сколько денег я получу?". Размер выплаты зависит от вашей <strong>официальной заработной платы</strong> и <strong>стажа социального страхования</strong>.</p><p>Пособие выплачивается в размере <strong>100%</strong> вашего среднего заработка за период отпуска (126 дней).</p><p><strong>Простая формула расчёта:</strong></p><ul><li><p><strong>Средний дневной заработок:</strong> Разделите сумму официальной заработной платы, полученной за последние 12 месяцев, на 30,4 (среднее количество дней в месяце). <em>(Грубо говоря, разделите свою зарплату на 30)</em>.</p></li><li><p><strong>Итоговая сумма:</strong> Умножьте полученное число на 126 дней.</p></li></ul><p><strong>Пример:</strong></p><p>Предположим, ваша официальная зарплата (gross) составляет 1000 AZN.</p><ul><li><p>Дневной заработок: 1000 / 30.4 ≈ 32.89 AZN</p></li><li><p>Выплата по беременности и родам: 32.89 x 126 дней = <strong>4144 AZN</strong>.</p></li></ul><p></p><blockquote><p>Важно: С этой суммы не удерживаются налоги, и она полностью перечисляется на вашу карту.</p></blockquote><p>&gt;</p><h2>Оформление документов: что нужно делать?</h2><p>Чтобы уйти в декретный отпуск, выполните следующие действия:</p><ul><li><p><strong>Справка от врача:</strong> На 30-й неделе беременности (при двойне — на 28-й неделе) получите в женской консультации, где вы состоите на учёте, <strong>"листок нетрудоспособности" (бюллетень)</strong>.</p></li><li><p><strong>Передача по месту работы:</strong> Предоставьте этот документ в отдел HR (отдел кадров) или бухгалтерию по месту работы.</p></li><li><p><strong>Электронная система:</strong> Работодатель внесёт данные в электронную систему.</p></li><li><p><strong>Выплата:</strong> Деньги выплачивает не работодатель, а <strong>Государственный фонд социальной защиты (DSMF)</strong>. Средства перечисляются непосредственно на вашу карту.</p></li></ul><h2>Сохраняется ли за мной рабочее место?</h2><p>Да! Законодательство строго защищает беременных женщин и мам, имеющих детей в возрасте до 3 лет.</p><ul><li><p><strong>Увольнять нельзя:</strong> Работодатель не может уволить вас во время беременности или декретного отпуска.</p></li><li><p><strong>Должность сохраняется:</strong> После возвращения из отпуска вы имеете право продолжить работу на той же должности и с той же заработной платой.</p></li></ul><p></p><h2>Частично оплачиваемый социальный отпуск (по уходу за ребёнком)</h2><p>После окончания 126-дневного декретного отпуска вы не обязаны возвращаться на работу. При желании вы можете оформить "частично оплачиваемый социальный отпуск" до достижения ребёнком <strong>3 лет</strong>.</p><ul><li><p><strong>Размер выплаты:</strong> К сожалению, эта сумма не зависит от заработной платы и является фиксированной:</p></li></ul><p>- До достижения ребёнком 1.5 лет: <strong>44 AZN</strong> в месяц.</p><p>- От 1.5 до 3 лет: <strong>28 AZN</strong> в месяц.</p><ul><li><p>В течение этого периода ваше рабочее место также сохраняется за вами.</p></li></ul><p></p><p>Декретный отпуск — это не пауза в вашей карьере, а время, которое вы посвящаете самому важному "проекту" своей жизни — своему ребёнку. Знайте свои права и пользуйтесь ими в полной мере.</p><p>Чтобы рассчитать точную сумму, которая вам положена, воспользуйтесь <strong>"Декретным калькулятором" в приложении Anacan</strong>. Просто введите свою зарплату, а остальное рассчитает приложение.</p>') WHERE id = '8d83fe70-b8fd-4c76-9c33-0e1fab0d6794';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Когда делать тест на беременность? Золотые правила для точного результата'), excerpt_ru = COALESCE(excerpt_ru, 'Когда следует делать тест на беременность? Нужно ли ждать задержки менструации или можно провериться раньше? Всё, что вам нужно знать о лучшем времени суток для получения точного результата и гормоне ХГЧ.'), content_ru = COALESCE(content_ru, '<p>Когда вы пытаетесь забеременеть или подозреваете беременность, ожидание может казаться самым сложным делом на свете. Каждый раз, заходя в аптеку, вы смотрите на маленькие коробочки на полке и думаете: «Может, проверить прямо сейчас?» Однако спешка часто приводит к разочарованию — «ложноотрицательному» результату или лишнему стрессу.</p><p>Так когда же наступает идеальное время, чтобы увидеть эти две заветные полоски? Есть ли разница, делать тест утром или вечером? В этой статье мы собрали всю важную информацию о тестах на беременность, чтобы помочь вам сберечь деньги и нервы.</p><h2>Как работают тесты на беременность? (Гормон ХГЧ)</h2><p>Чтобы понять, когда следует делать тест, сначала нужно узнать, что именно он определяет. Все домашние тесты на беременность предназначены для выявления в моче особого гормона — <strong>ХГЧ (хорионического гонадотропина человека)</strong>.</p><ul><li><p><strong>Процесс:</strong> После прикрепления оплодотворённой яйцеклетки к стенке матки (имплантации) плацента начинает вырабатывать этот гормон.</p></li><li><p><strong>Срок:</strong> Уровень ХГЧ удваивается каждые 2-3 дня. Однако, чтобы тест смог его «увидеть», концентрация гормона должна достичь определённого уровня.</p></li></ul><p></p><p>Если вы сделаете тест слишком рано, уровень ХГЧ может ещё не достичь порога чувствительности теста, даже если вы беременны. Результат? Одна полоска и напрасное огорчение.</p><h2>Самое подходящее время для проведения теста</h2><p>Главное правило здесь — набраться терпения. Существуют два основных подхода:</p><h3>1. Самый точный результат: после задержки менструации</h3><p>Большинство врачей и производителей тестов рекомендуют <strong>дождаться задержки менструации</strong> — то есть подождать как минимум 1 день после предполагаемой даты её начала.</p><ul><li><p><strong>Причина:</strong> К этому времени у большинства женщин уровень ХГЧ становится достаточным для определения стандартными тестами. Точность тестов в этот период приближается к 99%.</p></li></ul><p></p><h3>2. Для тех, кому не терпится: до задержки (ранние тесты)</h3><p>Производители некоторых тестов «Ранний результат» (Early Detection) заявляют, что они могут показать результат за 4-5 дней до предполагаемой менструации. Такие тесты обладают более высокой чувствительностью и определяют ХГЧ в меньшей концентрации.</p><ul><li><p><strong>Риск:</strong> Если вы получили отрицательный результат, это ещё не означает, что беременности нет. Возможно, тест просто был сделан слишком рано. В таком случае его следует повторить через несколько дней.</p></li></ul><p></p><h2>В какое время суток лучше делать тест? Утром или вечером?</h2><p>Утверждение о том, что тест обязательно нужно делать утром, — не просто миф, а научно обоснованная рекомендация.</p><ul><li><p><strong>Первая утренняя моча:</strong> Она имеет наиболее высокую концентрацию, поскольку накапливается в течение ночи. Концентрация гормона ХГЧ в ней максимальна. На раннем сроке — до задержки или в день предполагаемой менструации — тест необходимо делать утром.</p></li><li><p><strong>Днём и вечером:</strong> Если менструация задерживается уже на 1-2 недели, уровень ХГЧ обычно настолько высок, что тест можно делать в любое время суток.</p></li></ul><p></p><blockquote><p>Важное примечание: чрезмерное употребление воды или чая перед тестом разбавляет мочу и снижает концентрацию ХГЧ. Это может привести к ложноотрицательному результату.</p></blockquote><p>&gt;</p><h2>Ложноотрицательные и ложноположительные результаты</h2><p>Иногда тесты могут вводить нас в заблуждение. Важно знать возможные причины:</p><h3>Ложноотрицательный результат (вы беременны, но тест показывает «нет»)</h3><ul><li><p><strong>Причина 1:</strong> Вы сделали тест слишком рано — это самая распространённая причина.</p></li><li><p><strong>Причина 2:</strong> Моча была слишком разбавленной, поскольку вы выпили много воды.</p></li><li><p><strong>Причина 3:</strong> Истёк срок годности теста.</p></li></ul><p></p><h3>Ложноположительный результат (вы не беременны, но тест показывает «да»)</h3><p>Такое случается реже, но всё же возможно:</p><ul><li><p><strong>Биохимическая беременность:</strong> Оплодотворение произошло, но эмбрион не продолжил развиваться.</p></li><li><p><strong>Линия испарения:</strong> Бледная серая линия, которая появляется после истечения времени, отведённого для оценки результата теста (обычно 5-10 минут). Это не положительный результат.</p></li><li><p><strong>Некоторые препараты:</strong> Лекарственные средства для лечения бесплодия, содержащие ХГЧ, могут повлиять на результат.</p></li></ul><p></p><h2>Когда следует сдавать анализ крови на ХГЧ?</h2><p>Если результаты домашних тестов вызывают у вас сомнения или вы хотите получить более точный результат, анализ крови — самый надёжный способ.</p><ul><li><p>Анализ крови определяет ХГЧ раньше, чем анализ мочи, — через 7-10 дней после оплодотворения — и даёт более точный результат.</p></li><li><p>Этот анализ также показывает точное количество гормона (бета-ХГЧ), помогая оценить срок беременности и проследить, нормально ли она развивается.</p></li></ul><p></p><h2>5 золотых правил для точного результата</h2><p>При использовании домашнего теста на беременность обязательно соблюдайте следующие рекомендации:</p><ul><li><p><strong>Проверьте дату:</strong> При покупке теста обязательно проверьте срок его годности. Просроченные тесты могут давать неверный результат.</p></li><li><p><strong>Прочитайте инструкцию:</strong> Правила использования могут различаться в зависимости от производителя — например, время контакта теста с мочой.</p></li><li><p><strong>Дождитесь утра:</strong> Для наиболее точного результата используйте первую утреннюю мочу сразу после пробуждения.</p></li><li><p><strong>Засеките время:</strong> Оценивайте результат в промежуток времени, указанный в инструкции, например через 3-5 минут. Не доверяйте полоскам, появившимся спустя 10 минут.</p></li><li><p><strong>Повторите тест:</strong> Если результат отрицательный, но менструация всё ещё не началась, повторите тест через 2-3 дня.</p></li></ul><p>Проведение теста на беременность — волнительный момент, а ожидание результата может показаться вечностью. Лучшая стратегия — дать организму немного времени и дождаться хотя бы предполагаемого дня начала менструации.</p><p>Если результат положительный — поздравляем! Вас ждёт удивительное путешествие. Теперь следующий шаг — записаться на приём к врачу и загрузить <strong>приложение Anacan</strong>, чтобы следить за развитием малыша неделю за неделей. Если результат отрицательный, не расстраивайтесь: возможно, вы просто сделали тест слишком рано.</p>') WHERE id = '72759d73-a450-4336-884b-029f51312d47';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Развитие плода: что происходит с малышом и вашим телом в 1-м триместре?'), excerpt_ru = COALESCE(excerpt_ru, 'Как развивается ваш малыш в первые 12 недель беременности (1-й триместр)? Когда можно услышать сердцебиение? Всё об изменениях в организме мамы и удивительном пути от одной клетки до человека.'), content_ru = COALESCE(content_ru, '<p>Момент, когда вы видите две полоски на тесте на беременность, — один из самых незабываемых в жизни. Радость, волнение, возможно, немного страха... Все эти чувства совершенно нормальны. Внешне вы, возможно, ещё не изменились, но внутри вас происходит величайшее чудо Вселенной: зарождается новая жизнь.</p><p>Первые три месяца беременности, то есть <strong>1-й триместр</strong>, — самый важный период для развития малыша, когда изменения происходят особенно быстро. Всего за 12 недель одна невидимая глазу клетка превращается в крошечного человечка с бьющимся сердцем, ручками и ножками. Давайте подробнее рассмотрим, что в этот волшебный период происходит с вашим малышом и вашим телом.</p><h2>Что такое 1-й триместр? (1-12-я недели)</h2><p>Беременность делится на три этапа (триместра). Первый триместр начинается с первого дня последней менструации и продолжается до конца 12-й недели. Это важнейший этап формирования органов малыша ("органогенез"). Именно поэтому в первые месяцы решающую роль играют здоровый образ жизни и правильное питание.</p><h2>Как меняется ваш малыш? От микроскопической клетки до малыша размером со "сливу"</h2><h3>1-й месяц: Закладка основы (1-4-я недели)</h3><p>В первые две недели беременности формально вы ещё не беременны (ваш организм готовится к овуляции). Но после оплодотворения начинается настоящее приключение.</p><ul><li><p><strong>От зиготы до бластоцисты:</strong> Оплодотворённая яйцеклетка (зигота) быстро делится, продвигается к матке и прикрепляется к её стенке (имплантация).</p></li><li><p><strong>Размер:</strong> К концу месяца ваш малыш размером с <strong>маковое зёрнышко</strong>.</p></li><li><p><strong>Основные этапы развития:</strong> Начинает формироваться <strong>нервная трубка</strong>, из которой впоследствии развиваются головной и спинной мозг малыша. (См.: <em>Почему фолиевая кислота так важна?</em>).</p></li></ul><p></p><h3>2-й месяц: Сердце начинает биться! (5-8-я недели)</h3><p>В этом месяце развитие происходит особенно активно. Теперь ваш малыш называется "эмбрионом".</p><ul><li><p><strong>Сердце:</strong> Примерно на 6-й неделе сердце малыша начинает биться! Сердцебиение можно услышать во время УЗИ (ультразвукового исследования). Сердце работает очень быстро — 100-160 ударов в минуту.</p></li><li><p><strong>Черты лица:</strong> Начинают формироваться глаза, уши и нос.</p></li><li><p><strong>Конечности:</strong> Ручки и ножки сначала выглядят как маленькие почки, а к концу месяца уже начинают различаться пальчики.</p></li><li><p><strong>Размер:</strong> На 8-й неделе ваш малыш размером примерно с <strong>ягоду малины</strong> или <strong>фасолину</strong>.</p></li></ul><p></p><h3>3-й месяц: Человеческий облик (9-12-я недели)</h3><p>Стадия "эмбриона" завершается, и теперь ваш малыш называется "плодом" (фетусом).</p><ul><li><p><strong>Движения:</strong> Малыш начинает двигаться, но вы пока этого не чувствуете (для этого ещё слишком рано!).</p></li><li><p><strong>Органы:</strong> Все основные органы (почки, кишечник, головной мозг) уже сформировались и начинают работать. Появляются ногти.</p></li><li><p><strong>Пол:</strong> Формируются половые органы, однако увидеть их на УЗИ пока может быть слишком рано.</p></li><li><p><strong>Размер:</strong> К концу триместра ваш малыш размером с <strong>лимон</strong> или <strong>сливу</strong> (примерно 5-6 см).</p></li></ul><p></p><h2>А что происходит с вашим телом?</h2><p>Пока малыш быстро растёт, в вашем организме бушует настоящий "гормональный шторм". Хотя внешне изменения могут быть ещё незаметны, внутри идёт огромная работа.</p><h3>1. Утомляемость и слабость</h3><p>Вам постоянно хочется спать? Это связано с повышением уровня гормона прогестерона. Ваш организм расходует много энергии на формирование плаценты. Отнеситесь к себе с пониманием и старайтесь больше отдыхать.</p><h3>2. Утренняя тошнота (токсикоз)</h3><p>С этим состоянием сталкиваются около 70% беременных. Тошнота может возникать в любое время суток. Повышенная чувствительность к запахам — ещё один частый "спутник" этого периода. (Хорошая новость: во втором триместре эти проявления обычно проходят).</p><h3>3. Чувствительность груди</h3><p>Грудь может увеличиться, стать тяжелее и очень чувствительной к прикосновениям. Молочные железы уже начинают готовиться к лактации.</p><h3>4. Частое мочеиспускание</h3><p>Растущая матка давит на мочевой пузырь, а усиление кровообращения заставляет почки работать активнее.</p><h3>5. Перепады настроения (Mood Swings)</h3><p>Смеяться в одну минуту и плакать в следующую — совершенно нормально. Гормоны влияют на химические процессы в головном мозге.</p><h2>Важные рекомендации для 1-го триместра</h2><p>На что следует обратить внимание, чтобы благополучно пройти этот важный период?</p><ul><li><p><strong>Не забывайте о витаминах:</strong> Ежедневно принимайте назначенную врачом <strong>фолиевую кислоту</strong> или пренатальные витамины.</p></li><li><p><strong>Откажитесь от вредных привычек:</strong> Курение (в том числе пассивное) и алкоголь напрямую вредят развитию малыша.</p></li><li><p><strong>Следите за питанием:</strong> Избегайте сырого мяса, сырых яиц, непастеризованных молочных продуктов и рыбы с высоким содержанием ртути.</p></li><li><p><strong>Посетите врача:</strong> Пройдите первый гинекологический осмотр. Возможность услышать сердцебиение малыша подарит вам огромную радость и уверенность.</p></li><li><p><strong>Пейте воду:</strong> При токсикозе организм теряет много жидкости, поэтому старайтесь пить больше воды.</p></li></ul><p>Первый триместр — один из самых сложных и одновременно самых удивительных периодов беременности. Изменения в организме могут утомлять вас, но помните: каждый симптом может быть признаком того, что ваш малыш растёт.</p><p>Скачайте <strong>приложение Anacan</strong>, чтобы следить за развитием малыша по неделям, узнавать, с каким фруктом он сейчас сопоставим по размеру, и отмечать изменения в своём теле. Мы рядом с вами на каждом шагу этого удивительного пути!</p>') WHERE id = 'bebf165d-00e1-4178-b2e2-d7015c249b08';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Набор веса во время беременности: что считается нормой и как избежать лишнего веса?'), excerpt_ru = COALESCE(excerpt_ru, 'Сколько килограммов нормально набрать во время беременности? Таблица идеальной прибавки веса по индексу массы тела (ИМТ), риски избыточного веса и правда о мифе «есть за двоих».'), content_ru = COALESCE(content_ru, '<p>После того как вы сообщаете о беременности, все вокруг начинают предлагать вам еду: <em>«Ешьте, дорогая, теперь вам нужно есть за двоих!»</em>. Хотя эта фраза звучит приятно (особенно если перед вами вкусный торт), современная медицина утверждает совершенно обратное.</p><p>Для одних будущих мам растущие цифры на весах становятся источником радости, а для других — причиной стресса. Изменения тела и округление форм естественны, но где проходит граница? Какие показатели считаются здоровыми, а какие — рискованными?</p><p>В этой статье мы рассмотрели научно обоснованные нормы прибавки веса во время беременности, выяснили, на что на самом деле приходятся набранные килограммы и как сохранить здоровую форму.</p><h2>Какой должна быть идеальная прибавка веса? (Таблица ИМТ)</h2><p>Все женщины разные, поэтому «единой нормы для всех» не существует. То, сколько веса вам следует набрать, зависит от ваших роста и веса до беременности, то есть от <strong>индекса массы тела (ИМТ)</strong>.</p><p>Рекомендации международных медицинских организаций (IOM) выглядят следующим образом:</p><p>| Состояние до беременности | ИМТ (BMI) | Идеальная прибавка веса |</p><p>| --- | --- | --- |</p><p>| <strong>Дефицит веса</strong> | Менее 18.5 | <strong>12.5 – 18 кг</strong> |</p><p>| <strong>Нормальный вес</strong> | 18.5 – 24.9 | <strong>11.5 – 16 кг</strong> |</p><p>| <strong>Избыточный вес</strong> | 25.0 – 29.9 | <strong>7 – 11.5 кг</strong> |</p><p>| <strong>Ожирение</strong> | 30.0 и выше | <strong>5 – 9 кг</strong> |</p><p>| <strong>Беременность двойней</strong> | - | <strong>16 – 24 кг</strong> |</p><blockquote><p>Примечание: во время беременности не рекомендуется пытаться похудеть, даже при наличии избыточного веса. Цель — контролировать прибавку веса.</p></blockquote><p>&gt;</p><h2>Куда уходят эти килограммы? (Математический расчёт)</h2><p>Женщины часто думают, что все набранные 15 килограммов — это жир. К счастью, это не так! Набранный вес на самом деле расходуется на создание «системы жизнеобеспечения», необходимой для питания и защиты малыша.</p><p>В среднем прибавка веса на 13-14 кг распределяется примерно следующим образом:</p><ul><li><p><strong>Малыш:</strong> ~3.5 кг</p></li><li><p><strong>Плацента:</strong> ~0.7 кг</p></li><li><p><strong>Амниотическая жидкость (околоплодные воды):</strong> ~1 кг</p></li><li><p><strong>Матка (увеличившийся орган):</strong> ~1 кг</p></li><li><p><strong>Молочные железы:</strong> ~1 кг</p></li><li><p><strong>Увеличившийся объём крови:</strong> ~1.5 кг</p></li><li><p><strong>Жидкость в организме (отёчность):</strong> ~1.5 кг</p></li><li><p><strong>Жировые запасы (энергия для родов и грудного вскармливания):</strong> ~3-4 кг</p></li></ul><p></p><p>Как видите, значительная часть этого веса уйдёт сразу после родов и в первые недели.</p><h2>Миф о том, что нужно «есть за двоих»</h2><p>Самое распространённое заблуждение — считать, что беременной женщине требуется вдвое больше калорий.</p><ul><li><p><strong>1-й триместр:</strong> Потребности в дополнительных калориях <strong>НЕТ</strong>. Достаточно обычного сбалансированного питания.</p></li><li><p><strong>2-й триместр:</strong> Необходимо добавить примерно <strong>+340 ккал</strong> в день (это всего лишь один сэндвич или одна пиала йогурта).</p></li><li><p><strong>3-й триместр:</strong> Примерно <strong>+450 ккал</strong> в день (столько содержит полезный перекус).</p></li></ul><p></p><p>То есть нужно есть не за двоих, а <strong>для двоих — выбирая качественную пищу</strong>.</p><h2>Риски чрезмерной прибавки веса</h2><p>Прибавка веса сверх нормы — не просто эстетическая проблема. Она может создавать серьёзные риски как для мамы, так и для малыша:</p><ul><li><p><strong>Гестационный диабет:</strong> Повышается риск диабета беременных.</p></li><li><p><strong>Преэклампсия:</strong> Повышенное артериальное давление и появление белка в моче.</p></li><li><p><strong>Крупный плод (макросомия):</strong> Вес малыша более 4 кг может осложнить роды.</p></li><li><p><strong>Вероятность кесарева сечения:</strong> Из-за крупного плода или осложнений повышается риск хирургического вмешательства.</p></li><li><p><strong>Трудности после родов:</strong> Избавиться от лишних килограммов становится сложнее.</p></li></ul><h2>5 золотых правил здоровой прибавки веса</h2><p>Как контролировать вес, не испытывая голода и не лишая малыша витаминов?</p><h3>1. Избегайте «пустых» калорий</h3><p>Сладкие напитки, упакованные сладости, фастфуд... Они дают вам энергию, но не приносят малышу никакой пользы. Когда хочется сладкого, выбирайте фрукты, сухофрукты или тёмный шоколад.</p><h3>2. Выбирайте сложные углеводы</h3><p>Вместо белого хлеба выбирайте цельнозерновой, а вместо белого риса — гречку или булгур. Эти продукты поддерживают стабильный уровень сахара в крови и помогают дольше сохранять чувство сытости.</p><h3>3. Оставайтесь активной</h3><p>Беременность — не болезнь! Если ваш врач разрешает, ежедневные прогулки по 20-30 минут, плавание или йога для беременных помогут улучшить обмен веществ.</p><h3>4. Соблюдайте питьевой режим</h3><p>Иногда наш организм путает жажду с голодом. Достаточное количество воды в течение дня помогает регулировать аппетит и предотвращать отёчность.</p><h3>5. Регулярно следите за весом (приложение Anacan)</h3><p>Взвешивайтесь каждую неделю в один и тот же день и в одно и то же время (утром натощак). Следите за графиком с помощью функции <strong>«Трекер веса» в приложении Anacan</strong>. Приложение сразу покажет, соответствует ли ваш вес норме.</p><p>Прибавка веса во время беременности неизбежна и необходима. Главное — не зацикливаться на цифрах, а уделять внимание качеству питания. Ваше тело выполняет невероятную работу — относитесь к нему бережно и поддерживайте его полезной пищей.</p><p>Если вам не удаётся контролировать аппетит или вес быстро увеличивается, обязательно проконсультируйтесь с врачом. Баланс — залог здоровья мамы и малыша.</p>') WHERE id = 'e9b0858d-c2d3-46c9-9ba1-9fb87240b1be';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Менструация после родов: когда восстановится цикл? '), excerpt_ru = COALESCE(excerpt_ru, 'Когда начинается менструация после родов? Что такое «лактационная аменорея» у кормящих мам? Важная информация о восстановлении цикла, особенностях первой менструации и контрацепции.'), content_ru = COALESCE(content_ru, '<p>Первые недели после родов проходят в марафоне бессонных ночей, смены подгузников и кормлений грудью. И однажды среди всей этой суеты вы внезапно задумываетесь: <em>«У меня до сих пор не было менструации. Нормально ли это?»</em>.</p><p>Для одних женщин отсутствие менструации — большое облегчение (никаких дополнительных гигиенических хлопот!), а для других — повод для беспокойства («а вдруг я снова беременна?»).</p><p>На самом деле цикл после родов у каждой женщины восстанавливается по-разному, и главным образом это зависит от одного фактора: <strong>Как вы кормите малыша?</strong></p><p>В этой статье мы расскажем, как проходит этот процесс у кормящих и некормящих мам, насколько правдив миф о том, что «грудное вскармливание защищает», и чем первая менструация может отличаться от тех, что были до беременности.</p><h2>Лохии (послеродовое кровотечение) или менструация?</h2><p>Прежде всего необходимо различать эти два понятия. Кровянистые выделения, которые начинаются сразу после родов и продолжаются до 4-6 недель, — это не менструация, а <strong>лохии</strong>. Так происходит очищение и восстановление матки.</p><ul><li><p>После завершения лохий кровянистые выделения прекращаются. Если спустя некоторое время они появятся снова, это уже может быть первая менструация.</p></li></ul><h2>Сценарий 1: мамы, которые кормят исключительно грудью</h2><p>Если вы кормите малыша <strong>только</strong> грудным молоком (не даёте воду, прикорм или смесь) и часто прикладываете его к груди как днём, так и ночью, менструация может начаться значительно позже.</p><ul><li><p><strong>Причина:</strong> гормон <strong>пролактин</strong>, который вырабатывается во время грудного вскармливания, подавляет овуляцию. Если овуляции нет, менструация также не наступает. В медицине это называется <strong>лактационной аменореей</strong>.</p></li><li><p><strong>Срок:</strong> Менструация может отсутствовать от 6 месяцев до 1 года (иногда до завершения грудного вскармливания).</p></li><li><p><strong>Примечание:</strong> Как только малышу начинают давать прикорм или сокращается число ночных кормлений, уровень пролактина снижается и цикл восстанавливается.</p></li></ul><h2>Сценарий 2: мамы, которые кормят смесью</h2><p>Если малыш получает смесь или вы не кормите грудью, ваш организм быстрее выходит из «режима беременности» и возвращается к обычному состоянию.</p><ul><li><p><strong>Срок:</strong> Менструация обычно восстанавливается через <strong>6-8 недель после родов</strong> (примерно через 1.5 - 2 месяца).</p></li><li><p>Если спустя 3 месяца менструация всё ещё не началась, рекомендуется проконсультироваться с врачом.</p></li></ul><h2>Сценарий 3: смешанное вскармливание (грудное молоко + смесь)</h2><p>В этом случае сложно дать точный прогноз. Менструация может начаться как через 2-3 месяца после родов, так и позже. Всё зависит от частоты кормлений грудью.</p><h2>Какой будет первая менструация? (Изменения)</h2><p>Первая менструация после родов может отличаться от той, что была до беременности. Гормональный баланс вашего организма ещё не успел полностью восстановиться.</p><ul><li><p><strong>Кровотечение:</strong> Выделения могут быть более или менее обильными. Небольшие сгустки считаются нормой.</p></li><li><p><strong>Боль:</strong> Хорошая новость! Многие женщины — особенно те, кто страдал от боли из-за эндометриоза, — отмечают, что после родов менструальные боли значительно <strong>уменьшаются</strong> или полностью исчезают. Это связано с увеличением матки и гормональными изменениями.</p></li><li><p><strong>Регулярность:</strong> В первые несколько месяцев цикл может быть нерегулярным. Со временем он нормализуется.</p></li></ul><h2>Миф о том, что «грудное вскармливание защищает», и риск беременности</h2><p>Именно здесь кроется главная опасность. Многие женщины считают, что, если менструация ещё не началась, забеременеть невозможно. <strong>ЭТО НЕПРАВДА!</strong></p><ul><li><p><strong>Механизм:</strong> Примерно за 2 недели до менструального кровотечения происходит <strong>овуляция</strong>. То есть овуляция и беременность могут наступить ещё до того, как вы увидите первые кровянистые выделения.</p></li><li><p><strong>Вывод:</strong> Уверенность в том, что «грудное вскармливание меня защищает», может привести к незапланированной беременности-«сюрпризу» и рождению детей-погодок.</p></li></ul><h3>Когда метод лактационной аменореи (ЛАМ) защищает от беременности?</h3><p>Чтобы эффективность этого метода составляла 98%, <strong>обязательно</strong> должны соблюдаться 3 условия:</p><ol><li><p>Малышу меньше 6 месяцев.</p></li><li><p>Менструация ещё не восстановилась.</p></li><li><p>Малыш питается <strong>только</strong> грудным молоком (днём и ночью, каждые 4 часа).</p></li></ol><p>Если хотя бы одно из этих условий не соблюдается или вы не хотите рисковать, через 4-6 недель после родов обсудите с врачом <strong>контрацепцию</strong> (внутриматочную спираль, презервативы или подходящие кормящим мамам таблетки — «мини-пили»).</p><h2>Влияет ли менструация на количество молока?</h2><p>После восстановления менструации некоторые мамы могут заметить временное уменьшение количества молока. Это связано с гормональными изменениями.</p><ul><li><p><strong>Меняется ли вкус?</strong> Молоко может стать немного солоноватым, и малыш может несколько дней капризничать у груди. Наберитесь терпения — это временно.</p></li></ul><h2></h2><p>Менструация после родов — это способ вашего организма сказать: «Я уже восстановился и снова готов к материнству». Начнётся она через 2 месяца или через 1 год — оба варианта могут быть нормой.</p><p>Главное — предохраняться в этот период и быть готовой к неожиданностям.</p><p>Чтобы отслеживать цикл и не пропускать дни овуляции, скачайте приложение <strong>«Anacan»</strong>. Наше приложение использует специальный алгоритм для кормящих мам!</p>') WHERE id = '6fee7272-f8a5-4f87-8afd-dc09ac8b7012';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Приём лекарств во время беременности: что нужно знать о парацетамоле и антибиотиках?'), excerpt_ru = COALESCE(excerpt_ru, 'Какие лекарства можно принимать во время беременности? Безопасен ли парацетамол? Важная информация о приёме антибиотиков, рисках ибупрофена и категориях FDA. Руководство по лекарственным препаратам, которое поможет защитить вас и вашего малыша.'), content_ru = COALESCE(content_ru, 'До беременности при головной боли или первых признаках простуды мы, не задумываясь, тянулись к аптечке. Но после известия о беременности всё меняется. Теперь каждую таблетку мы воспринимаем как «потенциального врага».

С одной стороны — невыносимая боль или высокая температура, с другой — страх: *«Если я приму лекарство, не навредит ли оно моему малышу?»* Эта дилемма ставит многих будущих мам в тупик. Иногда страх бывает настолько сильным, что женщины отказываются даже от необходимого лечения, назначенного врачом.

Так где же истина? Каким лекарствам дан «зелёный свет», а какие находятся под строгим запретом? Давайте рассмотрим медицинские факты о препаратах, которые чаще всего применяются во время беременности.

## Золотое правило: НЕТ самолечению!

Прежде чем начать, напомним самое важное правило: **Во время беременности не принимайте никакие лекарства (даже растительного происхождения) без консультации с врачом.** Препарат, который помог вашей соседке, может не подходить вам с учётом срока беременности или вашего состояния.

## Парацетамол: «Спаситель» беременных

Во время беременности в качестве обезболивающего и жаропонижающего средства чаще всего рекомендуют **Парацетамол** (Панадол, Эффералган и т. д.).

### Почему он считается безопасным?

Медицинские исследования показывают, что при приёме парацетамола в рекомендованной дозе он не оказывает негативного влияния на развитие плода. Хотя препарат проникает через плаценту, токсического воздействия он не оказывает.

### Когда его следует принимать?

- **Высокая температура:** Температура выше 38°C во время беременности опаснее для малыша, чем лекарство. Высокая температура может ускорить сердцебиение плода и повредить структуру белков. Поэтому снижать температуру парацетамолом **необходимо**.
- **Боль:** При головной, зубной или мышечной боли лучше принять парацетамол, чем терпеть, поскольку это поможет снизить уровень гормонов стресса.

> Внимание: Несмотря на безопасность, препарат нельзя принимать «как конфеты». Используйте минимально возможную дозу в течение максимально короткого времени.
> 

## Антибиотики: друзья или враги?

В нашем обществе прочно укоренилось мнение, что «антибиотики вредны». Однако инфекции, которые не лечат во время беременности (например, инфекция почек, пневмония, инфекции, передающиеся половым путём), во много раз опаснее для малыша, чем антибиотики. Инфекция может привести к преждевременным родам, преждевременному излитию околоплодных вод и задержке развития плода.

Врачи назначают беременным только антибиотики из **безопасных групп**:

✅ **Разрешённые антибиотики:**

- **Группа пенициллинов:** (Например: Амоксициллин, Ампициллин). Это наиболее широко применяемая и безопасная группа.
- **Макролиды:** (Например: Эритромицин, Азитромицин). Назначаются при аллергии на пенициллины.
- **Цефалоспорины:** (Например: Цефалексин).

❌ **Запрещённые антибиотики:**

- **Тетрациклины:** Нарушают развитие костей малыша и вызывают появление стойких жёлтых пятен на зубах.
- **Стрептомицин:** Может повредить слуховой нерв плода (риск глухоты).
- **Левомицетин:** Может вызвать «синдром серого ребёнка».

**Вывод:** Если врач назначил вам антибиотик, значит, его польза значительно превышает возможный риск. Обязательно пройдите курс лечения полностью.

## Ибупрофен и аспирин: почему нужно соблюдать осторожность?

**Ибупрофен (Нурофен)** — один из самых популярных препаратов от головной боли — и другие нестероидные противовоспалительные препараты (НПВП) запрещены во время беременности, особенно **в 3-м триместре (после 28-й недели)**.

- **Риск:** Эти препараты могут вызвать преждевременное закрытие важного сосуда в сердце малыша (Ductus Arteriosus), что приводит к серьёзным проблемам с сердцем и лёгкими. Они также могут вызвать уменьшение количества околоплодных вод (олигогидрамнион).
- **Аспирин:** Его можно принимать только в том случае, если врач назначил его в специальной дозировке (например, «Кардиоаспирин» для снижения риска преэклампсии). Самостоятельное применение аспирина в качестве обезболивающего повышает риск кровотечения.

## Что делать при простуде и гриппе?

При сезонных заболеваниях продающиеся в аптеках «порошки в пакетиках» (Терафлю, Фервекс и т. д.) не подходят беременным, поскольку содержат вазоконстрикторы (сосудосуживающие вещества).

**Безопасные альтернативы:**

- **При заложенности носа:** Спреи с морской водой (Аквамарис и т. д.) полностью безопасны. Капли, содержащие ксилометазолин, можно использовать только с разрешения врача и в течение короткого времени (макс. 3 дня).
- **При боли в горле:** Полоскание солёной водой, тёплое молоко и мёд.
- **При кашле:** Сиропы на растительной основе (по назначению врача).

## Категории лекарственных препаратов при беременности (FDA)

При чтении информации на упаковке лекарства вы можете встретить эти буквы. Это классификация Управления по санитарному надзору за качеством пищевых продуктов и медикаментов США (FDA):

- **Категория A:** Препарат исследован с участием людей и полностью безопасен (Например: Фолиевая кислота).
- **Категория B:** Безопасен для животных; достаточных исследований с участием людей нет, однако препарат считается безопасным (Например: Парацетамол, Амоксициллин).
- **Категория C:** Оказал негативное воздействие на животных, данных о применении у людей мало. Используется только в том случае, если польза превышает риск.
- **Категория D:** Риск для плода человека доказан. Используется только при угрозе жизни.
- **Категория X:** Строго запрещён (Тератогенен). Наносит серьёзный вред плоду.


Беременность не означает, что вы должны оставаться «беззащитной» перед болезнями. Современная медицина предлагает достаточно безопасных средств, позволяющих вылечить маму и одновременно защитить малыша.

Если вы сомневаетесь, можно ли принимать тот или иной препарат, загрузите приложение **Anacan**. В разделе «База безопасности» (Safety Lookup) вы можете мгновенно проверить статус применения сотен лекарств во время беременности (Зелёный/Жёлтый/Красный).

Будьте здоровы, чтобы и ваш малыш рос здоровым!') WHERE id = 'eae5c8e3-deb5-4e7b-bbd0-bcd7ad980854';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Скачки роста: как понять, почему ваш малыш внезапно стал беспокойным'), excerpt_ru = COALESCE(excerpt_ru, 'Научное руководство, которое поможет понять, почему ваш малыш внезапно стал беспокойным, часто испытывает голод и плохо спит. Скачки роста, сроки их наступления и практические советы для родителей — в Anacan.'), content_ru = COALESCE(content_ru, '<p>Режим сна вашего малыша налажен, питание в норме, и вы наконец можете немного отдохнуть. Но внезапно, без видимой причины, всё меняется. Малыш становится беспокойным, часто плачет, не хочет слезать с рук, плохо спит и, что особенно заметно, постоянно просит грудь. Для родителей этот период может быть очень утомительным и тревожным. Но не волнуйтесь: чаще всего такое поведение указывает на важный этап развития малыша — <strong>скачок роста</strong>.</p><p>В разговорной речи такие периоды иногда называют "атаками", однако с научной точки зрения это кратковременный этап, во время которого у малыша происходит скачок как физического развития (увеличение роста и веса), так и неврологического (развитие мозга и освоение новых навыков). Когда происходят эти скачки, каковы их признаки и что вам следует делать в этот период? Давайте подробно разберёмся.</p><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776342350019-o7revwlpsy.png"><h2>1. Что такое скачок роста и как он происходит?</h2><p>Скачки роста — естественная и необходимая часть развития малыша. В этот период в его организме действительно происходят физические изменения: кости удлиняются, мышечная масса увеличивается, а объём мозга растёт.</p><p>Одновременно происходят и скачки неврологического развития. В мозге малыша формируются новые нейронные связи, благодаря которым он начинает по-новому воспринимать окружающий мир и осваивает новые навыки (например, видит на большем расстоянии, реагирует на звуки, начинает ползать и т. д.). Столь быстрые изменения стимулируют нервную систему малыша, что может приводить к беспокойству и нарушениям сна.</p><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776342395505-5nqqcbxzq5r.png"><h2>2. Основные признаки скачка роста</h2><p>Хотя каждый малыш индивидуален, во время скачка роста чаще всего наблюдаются следующие общие признаки:</p><ul><li><p><strong>Частый голод (классический признак):</strong> Малыш начинает испытывать голод чаще, чем при обычном режиме кормления. Это естественная реакция организма, позволяющая обеспечить его энергией, необходимой для быстрого роста.</p></li><li><p><strong>Нарушение сна:</strong> Малыш спит меньше обычного, часто просыпается или с трудом засыпает. Из-за того что неврологическое развитие активизирует работу мозга, малышу бывает трудно уснуть.</p></li><li><p><strong>Беспокойство и желание быть на руках:</strong> Быстрые изменения вызывают у малыша стресс, он чувствует себя менее защищённым и сильнее нуждается в маминых объятиях.</p></li><li><p><strong>Появление новых навыков:</strong> В конце периода скачка вы можете заметить, что малыш научился чему-то новому (например, впервые самостоятельно сел, потянулся к предмету или начал издавать новые звуки).</p></li></ul><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776342406239-ccasg9au4w.png"><h2>3. Когда происходят скачки роста?</h2><p>Хотя каждый малыш уникален, специалисты определили примерные сроки скачков роста (атак). Обычно они происходят в следующие периоды:</p><ul><li><p><strong>1-3 недели</strong></p></li><li><p><strong>6-8 недель</strong></p></li><li><p><strong>3 месяца</strong></p></li><li><p><strong>6 месяцев</strong></p></li><li><p><strong>9 месяцев</strong></p></li></ul><p>Эти сроки приблизительны и могут различаться у каждого малыша. Некоторые скачки длятся несколько дней, а другие — дольше (например, 1 неделю).</p><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776342425961-o24li10ye3.png"><h2>4. Что следует делать родителям во время скачка роста?</h2><p>Хотя этот период может быть утомительным, самое важное, что вы можете дать своему малышу, — это терпение, любовь и понимание. Вот несколько практических советов для родителей:</p><ul><li><p><strong>Кормите по требованию:</strong> Кормите малыша всякий раз, когда он просит грудь. Ваше грудное молоко (или молочная смесь) обеспечивает его возросшие потребности в энергии. Частое прикладывание к груди также естественным образом увеличивает выработку молока.</p></li><li><p><strong>Сохраняйте терпение и выдержку:</strong> Помните, что малыш капризничает не намеренно — он просто пытается справиться с изменениями в своём организме. Чаще берите его на руки, обнимайте, ласкайте и дарите ему больше любви.</p></li><li><p><strong>Находите время для отдыха:</strong> Спите, когда спит ваш малыш. Отложите домашние дела или попросите супруга о поддержке. Забота о вашем психологическом и физическом здоровье очень важна для малыша.</p></li><li><p><strong>Используйте возможности приложения:</strong> Отмечая время кормления и сна малыша, вы сможете быстрее распознать период скачка роста и заранее к нему подготовиться.</p></li></ul><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776342438224-65o4qmnn38g.png"><h2>Преодолеем скачки вместе с Anacan</h2><p>Помните, что скачки роста — это временный период. Всё, что сегодня кажется трудным, через несколько дней останется позади, а малыш удивит вас новыми навыками. Отслеживая частоту кормлений, продолжительность сна и изменения в поведении малыша в разделе "Календарь кризисов" приложения <strong>Anacan</strong>, вы сможете более системно наблюдать за периодами скачков и легче их пережить. Кроме того, вы сможете предоставить педиатру точные, научно обоснованные сведения о развитии малыша. Anacan всегда рядом с вами!</p>') WHERE id = '90e1b3b4-2746-4aba-b753-1fa9faeb0dca';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Что такое эктопическая (трубная) беременность? Симптомы и риски'), excerpt_ru = COALESCE(excerpt_ru, 'Что такое эктопическая (внематочная) беременность и как она возникает? Боль в животе, кровотечение и другие скрытые признаки опасности. Всё, что нужно знать, чтобы снизить риски и сохранить шансы на будущую беременность.'), content_ru = COALESCE(content_ru, '<p>Новость о беременности должна быть радостным событием для каждой женщины. Однако иногда две полоски на тесте на беременность вместо радости могут принести тревогу. Согласно медицинской статистике, примерно 1-2% всех беременностей оказываются <strong>эктопическими (внематочными)</strong>.</p><p>Этот диагноз может звучать пугающе, но своевременное вмешательство спасает жизнь и сохраняет ваши шансы стать мамой в будущем. Как же отличить эктопическую беременность от нормальной? Какая боль считается "тревожным сигналом"? Давайте вместе разберёмся в этой важной теме.</p><h2>Что на самом деле представляет собой эктопическая беременность?</h2><p>При нормальной беременности оплодотворённая яйцеклетка проходит по маточным трубам, попадает в матку и начинает там развиваться.</p><p>При <strong>эктопической беременности</strong> оплодотворённая яйцеклетка не достигает матки и закрепляется по пути — чаще всего <strong>в маточной трубе (98%)</strong>. Поэтому такую беременность также называют "трубной". В очень редких случаях она может развиваться в яичнике, брюшной полости или шейке матки.</p><blockquote><p>Горькая правда: к сожалению, вне матки эмбрион не может выжить и нормально развиваться. Рост тканей может привести к разрыву трубы и внутреннему кровотечению, опасному для жизни женщины.</p></blockquote><p>&gt;</p><h2>Скрытая опасность: как распознать симптомы?</h2><p>Самая коварная особенность эктопической беременности заключается в том, что поначалу она выглядит совершенно нормально. Менструация задерживается, тест показывает положительный результат, могут появиться тошнота и чувствительность груди.</p><p>Однако между 4-й и 10-й неделями беременности могут возникнуть следующие тревожные симптомы:</p><h3>1. Острая боль в животе или области таза</h3><p>При нормальной беременности возможны лёгкие спазмы, но при эктопической беременности боль отличается:</p><ul><li><p>Обычно возникает острая, колющая боль <strong>только с одной стороны</strong> живота — справа или слева.</p></li><li><p>Боль может появляться и исчезать либо быть постоянной.</p></li></ul><p></p><h3>2. Необычное вагинальное кровотечение</h3><p>Такое кровотечение отличается от обычной менструации.</p><ul><li><p>Чаще всего выделения бывают менее обильными, <strong>коричневого цвета</strong> или водянистыми.</p></li><li><p>Иногда женщины принимают их за запоздалую менструацию и не понимают, что беременны.</p></li></ul><p></p><h3>3. Боль в кончике плеча (особый симптом)</h3><p>Как бы странно это ни звучало, это один из наиболее серьёзных признаков эктопической беременности. Если в положении лёжа вы чувствуете боль в кончике плеча, в месте соединения плеча с рукой, это может указывать на раздражение диафрагмы из-за внутреннего кровотечения. <strong>Немедленно вызовите скорую помощь по номеру 103.</strong></p><h3>4. Слабость и головокружение</h3><p>Внутреннее кровотечение может вызвать снижение артериального давления, бледность и обморок.</p><h2>Факторы риска: почему это происходит?</h2><p>С этим может столкнуться любая женщина, однако некоторые факторы повышают риск:</p><ul><li><p><strong>Эктопическая беременность в прошлом:</strong> если у вас уже была такая беременность, вероятность её повторения несколько выше.</p></li><li><p><strong>Воспалительные заболевания и инфекции:</strong> инфекции, передающиеся половым путём, такие как хламидиоз и гонорея, могут вызвать воспаление и образование рубцов в маточных трубах, препятствуя продвижению яйцеклетки.</p></li><li><p><strong>Операции на маточных трубах:</strong> риск повышается, если ранее вам проводили хирургическое вмешательство на маточных трубах.</p></li><li><p><strong>Курение:</strong> исследования показывают, что курение снижает сократительную активность маточных труб.</p></li><li><p><strong>Экстракорпоральное оплодотворение (IVF):</strong> хотя это случается редко, риск несколько повышается.</p></li><li><p><strong>Возраст:</strong> у женщин старше 35 лет риск выше.</p></li></ul><p></p><h2>Диагностика и лечение</h2><p>Если вы подозреваете эктопическую беременность, нельзя терять время. Для подтверждения диагноза врач использует два метода:</p><ul><li><p><strong>Анализ крови (бета-ХГЧ):</strong> при эктопической беременности уровень гормона ХГЧ растёт медленнее, чем при нормальной беременности, или колеблется.</p></li><li><p><strong>Ультразвуковое исследование (УЗИ):</strong> если тест положительный, но плодное яйцо в полости матки не определяется, врач обследует маточные трубы.</p></li></ul><h3>Методы лечения:</h3><ul><li><p><strong>Медикаментозное лечение (метотрексат):</strong> если срок беременности очень мал и труба не разорвалась, развитие беременности останавливают с помощью специальной инъекции, после чего организм постепенно рассасывает ткани. Это лучший способ сохранить маточную трубу.</p></li><li><p><strong>Хирургическое лечение (лапароскопия):</strong> если эмбрион достиг значительных размеров или возникло внутреннее кровотечение, проводят операцию через небольшие разрезы. В зависимости от ситуации маточную трубу можно сохранить или удалить.</p></li></ul><p></p><h2>Смогу ли я стать мамой после эктопической беременности?</h2><p>Это самый частый и самый важный вопрос. <strong>Ответ: да!</strong></p><p>Подавляющее большинство женщин после эктопической беременности успешно вынашивают нормальную, здоровую беременность и становятся мамами. Даже если одну маточную трубу пришлось удалить, при здоровой второй трубе шансы забеременеть естественным путём остаются высокими.</p><p>Просто при следующей беременности врач будет наблюдать за вами более внимательно и назначит раннее УЗИ — примерно на 6-й неделе, — чтобы убедиться, что плодное яйцо находится в матке.</p><p>Эктопическая беременность — тяжёлое испытание как физически, так и эмоционально. Дайте себе время пережить утрату и восстановиться. Всегда внимательно прислушивайтесь к сигналам своего организма.</p><p>Помните: ранняя диагностика помогает сохранить не только ваше здоровье, но и шансы стать мамой в будущем. Если вы планируете беременность или уже беременны, отмечайте свои симптомы в <strong>приложении Anacan</strong> и при любых подозрительных признаках немедленно свяжитесь с врачом.</p>') WHERE id = '826a0380-8af2-4ff8-93f7-a6b1116cdfb9';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Развитие зрения малыша: как и когда он начинает ясно видеть мир?'), excerpt_ru = COALESCE(excerpt_ru, 'Когда малыши начинают видеть мир ясно и в цвете? Научный гид Anacan о развитии зрения малыша по месяцам — от периода новорождённости до одного года.'), content_ru = COALESCE(content_ru, '<p>В первые дни, держа малыша на руках и глядя ему в глаза, вы часто думаете: <em>"Интересно, он меня видит? Он меня узнаёт?"</em> Хотя глаза малыша открыты с момента рождения, его зрение, в отличие от других органов чувств, например слуха и обоняния, ещё не сформировано полностью. Зрительная система проходит постепенный процесс развития, который продолжается месяцами и даже годами.</p><p>Как же происходит этот удивительный процесс — от первых дней, когда малыш видит всё "размыто", до месяцев, когда он начинает открывать для себя мир во всём многообразии красок? Давайте посмотрим на мир глазами вашего малыша — месяц за месяцем.</p><h2>Период новорождённости (0-1 месяц): Только вы и чёрно-белый мир</h2><p>В первые мгновения после рождения сетчатка глаза малыша и зрительный центр его мозга ещё не созрели полностью. Мир для него выглядит очень размытым, а глаза отличаются высокой чувствительностью к свету.</p><ul><li><p><strong>Расстояние фокусировки:</strong> Новорождённый малыш способен относительно чётко видеть лишь на расстоянии <strong>20-30 см</strong>. Удивительным образом именно такое расстояние обычно бывает между лицом мамы и глазами малыша во время кормления грудью! Природа словно предусмотрела его, чтобы малыш мог видеть ту, в ком больше всего нуждается, — свою маму.</p></li><li><p><strong>Цвета:</strong> В первые недели малыши ещё не различают цвета. Они видят мир в чёрных, белых и серых тонах. Именно поэтому в первые месяцы игрушки и карточки с высокой контрастностью — чёрно-белые, клетчатые или полосатые — лучше привлекают их зрительное внимание.</p></li></ul><h2>2-3 месяца: Пробуждение цветов и первые попытки следить за движением</h2><p>Начиная со второго месяца мир вашего малыша постепенно становится более чётким и красочным.</p><ul><li><p><strong>Знакомство с цветами:</strong> Цветовые рецепторы глаза — колбочки — начинают быстро развиваться. Обычно малыши сначала начинают различать <strong>красный</strong> цвет, а затем зелёный, жёлтый и синий. Однако близкие оттенки, например оранжевый и красный, они пока не различают.</p></li><li><p><strong>Слежение глазами:</strong> Малыш уже может следить глазами за движущимися предметами. Если медленно провести цветной игрушкой перед его глазами справа налево, вы заметите, что его взгляд, а иногда и голова движутся вслед за игрушкой.</p></li><li><p><strong>Зрительный контакт:</strong> В этот период малыш уже может подолгу смотреть вам в глаза и изучать выражение вашего лица. Это момент, когда эмоциональная связь между вами становится ещё глубже.</p></li></ul><h2>4-6 месяцев: Трёхмерный мир и зрительно-моторная координация</h2><p>Эти месяцы становятся периодом значительного скачка в развитии зрения. Острота зрения малыша быстро повышается.</p><ul><li><p><strong>Восприятие глубины (стереоскопическое зрение):</strong> Если раньше малыш воспринимал мир как плоский экран, то теперь он начинает одновременно фокусировать оба глаза и понимать глубину пространства — формируется трёхмерное зрение (3D).</p></li><li><p><strong>Захватывание и восприятие:</strong> Развитие восприятия глубины позволяет малышу оценивать расстояние до предметов. Благодаря этому он может протянуть руку и точно схватить игрушку. Это один из важнейших этапов развития <strong>зрительно-моторной координации</strong>.</p></li><li><p><strong>Все цвета:</strong> Теперь ваш малыш способен почти так же чётко, как взрослый, различать практически весь цветовой спектр, включая пастельные оттенки.</p></li></ul><h2>7-12 месяцев: Свобода движений и полная ясность</h2><p>В эти месяцы, когда малыш учится ползать и готовится сделать первые шаги, зрительная система становится его главным проводником.</p><ul><li><p>Ползание невероятно хорошо развивает не только зрительно-моторную координацию малыша, но и координацию всего тела. Теперь он легко видит любимую игрушку в другом углу комнаты, оценивает расстояние и направляется к ней.</p></li><li><p>Цвет его глаз уже полностью стабилизируется. К одному году зрение малыша становится почти таким же, как у взрослого.</p></li></ul><h2>Как поддержать развитие зрения вашего малыша?</h2><ul><li><p><strong>Первые 2 месяца:</strong> Разместите у края кроватки или возле пеленального столика <strong>контрастные чёрно-белые карточки</strong>.</p></li><li><p><strong>3-4 месяца:</strong> Подвесьте над кроваткой цветной вращающийся мобиль, чтобы малыш знакомился с цветами и учился следить за ним глазами.</p></li><li><p><strong>Регулярно меняйте положение малыша:</strong> Периодически меняйте его положение в кроватке, чтобы он смотрел на комнату под разными углами. Днём выкладывайте малыша на коврик и размещайте вокруг него разные игрушки.</p></li></ul><p></p>') WHERE id = 'c540f97b-d31c-44d4-af21-b75600cb74be';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Почему календарь менструаций так важен? 3 преимущества отслеживания цикла с «Anacan» для здоровья'), excerpt_ru = COALESCE(excerpt_ru, 'Почему важно отслеживать менструальный цикл? Скрытые преимущества календаря менструаций: раннее выявление заболеваний, контроль ПМС и предоставление врачу точной информации. Держите здоровье под контролем с приложением «Anacan».'), content_ru = COALESCE(content_ru, 'На приёме у гинеколога вам всегда задают один и тот же первый вопрос: «Когда у вас была последняя менструация?».
В этот момент многие женщины начинают судорожно вспоминать, называют приблизительные даты или неуверенно отвечают: «Кажется, в начале месяца, а может, в середине». Большинство женщин считают, что следить за календарём менструаций нужно лишь в двух случаях: если они хотят забеременеть или, наоборот, избежать беременности.

Но на самом деле менструальный цикл — это «пятый жизненно важный показатель» женского организма наряду с пульсом, температурой, артериальным давлением и дыханием. Это не просто дни кровотечения, а ежемесячный отчёт о здоровье, который посылает вам ваше тело.
Времена, когда эти дни отмечали в блокноте, остались в прошлом. Сегодня умные приложения, такие как «Anacan», позволяют справиться с этой задачей за считаные секунды. Так почему же каждой женщине важно следить за своим циклом? Давайте рассмотрим 3 главных преимущества для здоровья. 

1. Раннее выявление: как заметить сигналы «SOS» вашего организма
Менструальный цикл — зеркало гормонального здоровья. Внезапные изменения цикла могут быть первым признаком скрытых нарушений в организме.
При регулярном отслеживании вы понимаете, что является «нормой» именно для вас. Приложение Anacan помогает вовремя заметить следующие отклонения:
• Изменение продолжительности цикла: если цикл внезапно становится короче (менее 21 дня) или длиннее (более 35 дней), это может указывать на синдром поликистозных яичников (СПКЯ), заболевания щитовидной железы или гормональный дисбаланс.
• Мажущие выделения: кровотечения между менструациями могут указывать на полипы или миому.
• Интенсивность боли: отмечая в приложении степень боли, вы сможете понять, усиливается ли она со временем (это может вызвать подозрение на эндометриоз).
Благодаря приложению вы сможете заметить такие «отклонения» сразу, а не спустя несколько месяцев, и своевременно обратиться к врачу.

2. Контроль ПМС и перепадов настроения
Бывало ли так, что вы без видимой причины раздражались, плакали или хотели на всех накричать, а через 2 дня начиналась менструация? И тогда вы с облегчением думали: «А, вот в чём была причина!»
Предменструальный синдром (ПМС) для многих женщин становится настоящим кошмаром. Но если вы знаете, когда «придёт враг», то сможете к этому подготовиться.
С приложением «Anacan» вы получаете:
• Прогноз: приложение предупредит вас о приближении периода ПМС.
• Подготовка: вы будете знать, что на следующей неделе у вас может быть меньше энергии или вы станете более чувствительной. Благодаря этому вы сможете перенести важные встречи, отнестись к себе с большим пониманием или заменить сладости полезными альтернативами.
• Отслеживание симптомов: отмечая головную боль, набухание молочных желёз или высыпания, вы сможете увидеть закономерности, повторяющиеся каждый месяц.

3. Точное общение с врачом и правильное лечение
Вместо того чтобы на приёме у врача гадать: «Какого числа это было в прошлом месяце?», можно открыть приложение и предоставить точные сведения — а это уже половина диагностики.
Приложение «Anacan» служит вашей цифровой медицинской картой. Вы можете показать врачу не только дату последней менструации, но и следующие данные:
• Продолжительность и регулярность циклов за последние 6 месяцев.
• Объём кровотечения (обильное или скудное).
• Дни, когда начиналась боль.
• Дни половых контактов (для тех, кто планирует беременность).
Эта точная информация помогает врачу разобраться в причине проблемы и не назначать ненужные анализы.

Почему именно «Anacan»?
Хотя на мировом рынке существует множество приложений для отслеживания цикла, Anacan разработан специально для женщин Азербайджана:
• На родном языке: вам не придётся переводить медицинские термины со словарём.
• Локальный контент: рекомендации учитывают наш климат, пищевые привычки и образ жизни.
• Конфиденциальность: ваши данные надёжно защищены.

Вести календарь менструаций — значит не просто отмечать «красные дни», а уважать своё тело и учиться понимать его язык. Не оставляйте здоровье на волю случая.
Скачайте приложение «Anacan» уже сегодня, чтобы прислушиваться к сигналам своего организма. Оно станет вашим самым близким доверенным помощником и проводником в вопросах здоровья.') WHERE id = '7064d252-771f-4621-a7fc-347ed9fb6366';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Идеальных мам не бывает — бывают счастливые: как проявлять сострадание к себе на пути материнства'), excerpt_ru = COALESCE(excerpt_ru, 'Освободитесь от иллюзии «идеальной мамы» из социальных сетей! Что такое материнское чувство вины и как проявлять сострадание к себе? Руководство по психологической поддержке и мотивации для уставших мам — в Anacan.'), content_ru = COALESCE(content_ru, '<p>В тот момент, когда вы впервые берёте малыша на руки, вместе с огромной волной любви внутри вас начинает зарождаться и безмолвное давление: <em>«Я должна всё делать как можно лучше»</em>. Ожидания общества, строгие правила из книг и далёкие от реальности иллюзии, созданные социальными сетями, психологически истощают многих мам.</p><p>Иногда из-за недосыпа вам хочется плакать, пока малыш спит, вы вместо отдыха спешите заняться домашними делами или чувствуете себя виноватой из-за того, что разозлились. В психологии это называется <strong>«материнским чувством вины» (mom guilt)</strong>. Но помните: вашему малышу не нужна идеальная мама-робот, которая никогда не устаёт. Ему нужна просто счастливая, спокойная мама, способная дарить ему любовь. Так как же избавиться от этих иллюзий и научиться проявлять сострадание к себе?</p><h2>1. Иллюзия социальных сетей и «материнское чувство вины»</h2><p>Сегодня социальные сети — один из главных источников психологической нагрузки для мам. В Инстаграме и на других платформах мамы всегда выглядят ухоженными, их дома — безупречно чистыми, а малыши — улыбчивыми и беспроблемными. После просмотра таких видео мама, глядя на свой неубранный дом и плачущего малыша, невольно чувствует себя недостаточно хорошей.</p><p>На самом же деле то, что вы видите в социальных сетях, — лишь тщательно отобранные и обработанные фильтрами 15 секунд из сложного 24-часового дня. Никто не делится моментами, когда плачет от недосыпа в 3 часа ночи, когда подгорает еда или малыш в третий раз пачкает одежду. Перестаньте сравнивать себя с образами «идеальных мам» из социальных сетей. Реальность бывает беспорядочной и утомительной, но при этом совершенно естественной.</p><h2>2. Что означает в психологии концепция «достаточно хорошей матери»?</h2><p>Концепция <strong>«достаточно хорошей матери» (The good enough mother)</strong>, предложенная известным педиатром и психоаналитиком Дональдом Винникоттом (Donald Winnicott), — это основополагающая идея, о которой стоит знать каждой маме.</p><p>Винникотт отмечал, что для здорового психологического развития ребёнку не нужна идеальная мама, которая мгновенно удовлетворяет каждую его потребность и никогда не ошибается. Напротив, если мама иногда запаздывает, устаёт и допускает небольшие ошибки, это учит ребёнка принимать реальность, быть терпеливым и адаптироваться к внешнему миру. Если вы удовлетворяете основные физические и эмоциональные потребности малыша, дарите ему любовь и чувство безопасности, значит, вы уже достаточно хорошая мама!</p><h2>3. Забота о себе — не эгоизм, а биологическая необходимость</h2><p>Вспомните известное правило безопасности в самолёте: <em>«В чрезвычайной ситуации сначала наденьте кислородную маску на себя, а затем — на ребёнка».</em> Оно должно стать одним из основных принципов материнства. Когда вы физически и психологически истощены, вы не можете дать малышу необходимое ему тепло. Из пустого кувшина невозможно наполнить чужой стакан.</p><p>Выделять время на себя — не роскошь и не эгоизм, а необходимость для здоровья вашей семьи. Вы не обязаны тратить время сна малыша на глажку или уборку дома. Посвящайте хотя бы 15-20 минут в день тому, чтобы просто <strong>ничего не делать</strong>, выпить чашку горячего кофе, принять ванну или поговорить с любимой подругой. Ваше психическое здоровье — важнейшая среда для развития малыша.</p><h2>4. Научитесь просить о поддержке и распределять обязанности</h2><p>В нашем обществе существует ошибочное убеждение, что мама должна справляться со всем самостоятельно. Как гласит известная африканская пословица: <em>«Чтобы вырастить ребёнка, нужна целая деревня».</em> Не берите всё на себя. Позвольте супругу менять малышу подгузник, укладывать его спать или купать. (Даже если он делает это не так «идеально», как вы!). Не стесняйтесь просить помощи у бабушек, членов семьи или близких подруг. Принимать помощь — не значит быть слабой или неумелой мамой. Напротив, это показывает, что вы — осознанный человек, который знает границы своих возможностей.</p><h2>5. Помните, что с Anacan вы не одиноки</h2><p>Иногда вам может казаться, что только вы сталкиваетесь с этими трудностями. Но поверьте: тысячи мам прямо сейчас испытывают тот же недосып, те же тревоги и ту же усталость. Сообщество <strong>Anacan</strong> всегда рядом, чтобы вы могли поделиться своим опытом, страхами и даже признаться, что иногда устаёте. Здесь вы можете откровенно поговорить с мамами, которые не осудят вас, ведь они сами проходят через то же самое.</p><p>Помните: небольшой беспорядок в доме, задержка с приготовлением еды или непричёсанные волосы не определяют, насколько вы хорошая мама. Для своего малыша вы — лучшая мама в мире, и он очень любит вас со всеми вашими несовершенствами — просто за то, что вы есть. Будьте добрее к себе!</p>') WHERE id = 'b7f22f6c-c2d5-48b7-9360-a660921f6b3e';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Как рассчитать дату родов? Почему важна дата последней менструации (ДПМ)?'), excerpt_ru = COALESCE(excerpt_ru, 'Когда родится ваш малыш? Подробное руководство о самых точных способах расчёта даты родов, значении даты последней менструации (ДПМ) и правиле Негеле. Узнайте предполагаемую дату родов с помощью калькулятора.'), content_ru = COALESCE(content_ru, '<p>Как только будущая мама видит положительный результат теста на беременность, у неё возникает первый вопрос: <em>"Когда я смогу взять своего малыша на руки?"</em></p><p>Знать эту волшебную дату важно не только для подготовки детской комнаты или планирования ухода в декрет, но и для медицинского наблюдения за течением беременности. Однако эта дата часто вызывает путаницу. Почему врачи отсчитывают срок беременности не со дня оплодотворения, а от менструации? 40 недель — это на самом деле сколько месяцев?</p><p>Давайте простыми словами объясним логику этих расчётов и расскажем, как наиболее точно определить предполагаемую дату родов.</p><h2>Почему дата последней менструации (ДПМ) так важна?</h2><p>Многие женщины пытаются рассчитать срок беременности со дня, когда, по их мнению, произошло оплодотворение — то есть со дня полового контакта. Однако врач всегда спросит вас о <strong>первом дне последней менструации (ДПМ)</strong>.</p><p>Причина проста:</p><ul><li><p><strong>Точный день определить сложно:</strong> оплодотворение может произойти не в день полового контакта. Сперматозоиды способны сохранять жизнеспособность в организме женщины до 5 дней. Например, если половой контакт был в воскресенье, оплодотворение могло произойти в среду.</p></li><li><p><strong>Медицинский стандарт:</strong> первый день менструации служит точной отправной точкой. В медицине продолжительность беременности принимают за <strong>40 недель (280 дней)</strong>, и этот срок отсчитывают от ДПМ.</p></li></ul><p>Это означает, что в течение <strong>первых двух недель</strong> беременности технически вы ещё не беременны! Ваш организм только готовится к овуляции.</p><h2>Как рассчитать дату родов? (Правило Негеле)</h2><p>Самая популярная формула, которой пользуются врачи и наше приложение, — <strong>правило Негеле</strong>. Вы тоже можете легко выполнить расчёт самостоятельно:</p><blockquote><p>Формула: первый день последней менструации + 7 дней - 3 месяца + 1 год.</p></blockquote><p>&gt;</p><p><strong>Пример:</strong></p><p>Предположим, первый день вашей последней менструации — <strong>1 ноября 2025</strong> года.</p><ul><li><p><strong>Прибавьте 7 дней:</strong> 8 ноября.</p></li><li><p><strong>Отсчитайте 3 месяца назад:</strong> 8 августа.</p></li><li><p><strong>Прибавьте 1 год:</strong> 8 августа 2026.</p></li></ul><p><strong>Предполагаемая дата родов:</strong> 8 августа 2026.</p><p>Этот метод достаточно точен для женщин с регулярным 28-дневным менструальным циклом.</p><h2>А если цикл нерегулярный?</h2><p>Если ваш менструальный цикл короче или длиннее 28 дней (например, 35-40 дней), расчёт по правилу Негеле может быть менее точным. В таких случаях наиболее надёжным методом является <strong>раннее ультразвуковое исследование (УЗИ)</strong>.</p><ul><li><p><strong>УЗИ для уточнения срока:</strong> УЗИ, проведённое на 8-13-й неделе беременности, позволяет измерить копчико-теменной размер малыша (КТР) и определить срок беременности с максимальной точностью — с погрешностью 3-5 дней.</p></li><li><p>Если срок по УЗИ отличается от срока, рассчитанного по ДПМ, более чем на 7 дней, врач обычно ориентируется на данные УЗИ и корректирует предполагаемую дату родов ("скорректированная дата").</p></li></ul><p></p><h2>Дата родов — не "крайний срок", а ориентир!</h2><p>Знание этого поможет вам избежать лишнего стресса: только <strong>4-5%</strong> женщин рожают точно в рассчитанный день.</p><p>Ваш малыш может родиться:</p><ul><li><p><strong>на 2 недели раньше (на 38-й неделе)</strong> или</p></li><li><p><strong>на 2 недели позже (на 42-й неделе)</strong>. При приближении к 42-й неделе требуется особенно тщательное наблюдение врача, поскольку беременность с 42 недель считается переношенной.</p></li></ul><p></p><p>Дата родов лишь обозначает для вас примерное "временное окно". У малыша могут быть собственные планы!</p><h2>Упростите расчёты с приложением Anacan</h2><p>Не тратьте время, сверяясь с календарём и считая дни. "Калькулятор родов" в <strong>приложении Anacan</strong> учтёт всё за вас.</p><ul><li><p>Скачайте приложение.</p></li><li><p>Введите первый день последней менструации.</p></li><li><p>Система сразу покажет предполагаемую дату родов, текущую неделю беременности и знак зодиака вашего малыша.</p></li></ul><p>Знать предполагаемую дату родов важно, чтобы следить за беременностью, вовремя проходить скрининговые обследования и оценивать развитие малыша. Но не воспринимайте эту дату как "день экзамена". Ваш малыш появится на свет, когда будет готов.</p><p>А вам остаётся наслаждаться каждым мгновением этого 40-недельного путешествия и прислушиваться к своему телу. Желаем вам здоровой и счастливой встречи с малышом!</p>') WHERE id = '20146a03-c60f-4544-8ada-5b41516bd1a0';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Невыносимые боли при менструации (дисменорея): натуральные средства и когда обращаться к врачу?'), excerpt_ru = COALESCE(excerpt_ru, 'Почему во время менструации возникают сильные боли (дисменорея)? 5 натуральных способов облегчить боль в домашних условиях: тепло, травяные чаи и массаж. Признаки, позволяющие заподозрить эндометриоз, и случаи, когда необходимо обратиться к врачу'), content_ru = COALESCE(content_ru, '<p>С приближением этих дней месяца вы испытываете страх? В первые дни не можете встать с постели и вынуждены отпрашиваться с работы или занятий? Даже если окружающие обесценивают вашу боль, говоря: <em>"Такова женская доля, нужно терпеть"</em> или <em>"После замужества пройдёт"</em>, вы понимаете, что такая боль — не норма.</p><p>Болезненная менструация, которая на медицинском языке называется <strong>дисменореей</strong>, снижает качество жизни миллионов женщин во всём мире. Но "терпеть" — не единственный выход.</p><p>В этой статье мы разберём истинные причины спазмов, натуральные методы, которые можно попробовать до приёма обезболивающих, а также признаки того, что боль может быть симптомом серьёзного заболевания, например эндометриоза.</p><h2>Почему возникает боль? </h2><p>Во время менструации матка сокращается, чтобы вывести выстилающий её внутренний слой — эндометрий. Вещества, вызывающие эти сокращения, называются <strong>простагландинами</strong>.</p><ul><li><p><strong>Простое объяснение:</strong> чем выше уровень простагландинов, тем сильнее сокращается матка. Это временно ухудшает кровоснабжение и вызывает острую боль. Такое состояние называется <strong>первичной дисменореей</strong> и обычно встречается у молодых девушек.</p></li></ul><p>Но если боль вызвана другими причинами — кистой, миомой или эндометриозом, — это называется <strong>вторичной дисменореей</strong> и обязательно требует лечения.</p><h2>Скорая помощь дома: 5 натуральных средств</h2><p>Если вы не хотите принимать лекарство или желаете облегчить состояние, пока оно не подействует, попробуйте следующие методы:</p><h3>1. Тепло (грелка) — самый старый и эффективный метод</h3><p>Совет наших бабушек "положить тепло на живот" подтверждён наукой. Тепло расслабляет мышцы матки и улучшает кровообращение.</p><ul><li><p><strong>Как применять:</strong> положите бутылку с горячей водой, грелку или прогретое утюгом тёплое полотенце на нижнюю часть живота. Тёплый душ оказывает такой же эффект.</p></li></ul><h3>2. Чудодейственные травяные чаи</h3><p>Некоторые растения обладают натуральным спазмолитическим действием.</p><ul><li><p><strong>Ромашка:</strong> благодаря успокаивающему действию помогает расслабить и нервную систему, и мышцы.</p></li><li><p><strong>Имбирь:</strong> обладает выраженным противовоспалительным действием. Натрите свежий имбирь и заварите его как чай.</p></li><li><p><strong>Корица:</strong> помогает регулировать кровотечение и уменьшать боль.</p></li></ul><h3>3. Продукты, богатые магнием</h3><p>Магний — это "натуральный релаксант". За несколько дней до менструации увеличьте количество богатых магнием продуктов в рационе.</p><ul><li><p><strong>Что есть:</strong> бананы, тёмный шоколад (да, шоколад!), миндаль, шпинат и тыквенные семечки.</p></li></ul><h3>4. Массаж и эфирные масла</h3><p>Лёгкий массаж нижней части живота круговыми движениями может уменьшить спазмы.</p><ul><li><p><strong>Рецепт:</strong> добавьте несколько капель масла <strong>лаванды</strong> или <strong>мяты</strong> в небольшое количество базового масла — оливкового или миндального. Лаванда успокаивает, а мята помогает "притупить" боль.</p></li></ul><h3>5. Двигайтесь (не лежите, свернувшись на диване)</h3><p>Мы знаем, что во время боли движение — последнее, чего вам хочется. Но лёгкая прогулка или специальные упражнения из йоги, например "поза ребёнка" или "кошка-корова", стимулируют выработку эндорфинов, которые действуют как натуральное обезболивающее.</p><h2>Когда следует обратиться к врачу? </h2><p>Не все спазмы при менструации являются нормой. Если вы сталкиваетесь с перечисленными ниже ситуациями, это может быть не просто особенностью организма, а медицинской проблемой:</p><ol><li><p><strong>Лекарства не помогают:</strong> боль не проходит, несмотря на приём ибупрофена или других обезболивающих.</p></li><li><p><strong>Боль мешает вам жить:</strong> из-за неё вы не можете ходить на работу или занятия и заниматься повседневными делами.</p></li><li><p><strong>Продолжительность боли:</strong> спазмы начинаются за 2-3 дня до менструации и продолжаются даже после окончания кровотечения.</p></li><li><p><strong>Возрастной фактор:</strong> болезненные менструации внезапно начались не в юном возрасте, а после 25 лет.</p></li><li><p><strong>Другие симптомы:</strong> помимо боли наблюдаются необычные выделения, боль во время полового акта или проблемы с зачатием.</p></li></ol><p>Эти признаки могут указывать на <strong>эндометриоз</strong>, <strong>миому матки</strong> или <strong>кисты</strong>. Своевременная диагностика может избавить вас от многолетних страданий.</p><h2></h2><p>Боль при менструации — не "наказание" за то, что вы женщина. Ваше тело пытается вам что-то сказать. Попробуйте натуральные средства, позаботьтесь о себе — отдыхайте и пейте больше воды, — а если боль невыносима, обязательно проконсультируйтесь с гинекологом.</p><p>Чтобы отслеживать спазмы и видеть, в какие дни они усиливаются, скачайте <strong>приложение Anacan</strong>. Записывайте в дневнике приложения интенсивность боли по шкале от 1 до 10 и принимаемые лекарства — это поможет врачу поставить точный диагноз.</p>') WHERE id = '04145ab8-cc0f-4bf4-8e1f-5ff795884198';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Первые признаки беременности: как понять, что вы беременны, без теста?'), excerpt_ru = COALESCE(excerpt_ru, 'Как понять, что вы беременны, ещё до задержки менструации? Подробное руководство о ранних симптомах беременности, имплантационном кровотечении, базальной температуре и скрытых сигналах вашего организма.'), content_ru = COALESCE(content_ru, '<p>«Неужели я беременна?» — вероятно, это самый волнующий и, возможно, самый тревожный вопрос, который сейчас не даёт вам покоя. Делать аптечный тест на беременность ещё рано или, может быть, вам просто не хватает терпения дождаться результата. По мере приближения конца каждого менструального цикла вы начинаете следить за малейшими изменениями в организме: «Это просто усталость или всё-таки признак?»</p><p>К счастью, ваш организм начинает подавать определённые сигналы задолго до того, как тест покажет результат. Гормональные изменения запускаются сразу после оплодотворения. В этой статье мы расскажем, как можно почувствовать беременность без теста, какие симптомы появляются раньше всего и как отличить признаки беременности от ПМС (предменструального синдрома).</p><h2><strong>Что происходит в организме до задержки менструации?</strong></h2><p>Для многих женщин первым явным признаком беременности становится задержка менструации. Однако, если быть внимательной, организм может «сообщить новость» гораздо раньше. В первые недели беременности (с медицинской точки зрения — на 3-4-й неделях, если считать от первого дня последней менструации) повышение уровня прогестерона и ХГЧ вызывает ряд физиологических изменений.</p><h3><strong>Имплантационное кровотечение и мажущие выделения</strong></h3><p>Примерно через 6-12 дней после оплодотворения эмбрион прикрепляется к стенке матки. Во время этого процесса у некоторых женщин появляются небольшие мажущие выделения розового или коричневого цвета. В медицине это называется <strong>имплантационным кровотечением</strong>.</p><ul><li><p><strong>Как отличить?</strong> Такое кровотечение гораздо скуднее обычной менструации, длится недолго (иногда всего несколько часов) и обычно не сопровождается болью. Если вы заметили на нижнем белье лишь несколько капель или небольшое пятно, это может быть первым «приветом» беременности.</p></li></ul><p></p><h3><strong>Сохранение повышенной базальной температуры</strong></h3><p>Если для отслеживания овуляции вы каждое утро измеряете <strong>базальную температуру</strong>, её график может дать вам наиболее точную подсказку. В норме после овуляции температура повышается, а с приближением менструации снижается.</p><ul><li><p><strong>Признак беременности:</strong> Если температура остаётся повышенной более 2 недель и не снижается, это с большой вероятностью может указывать на беременность.</p></li></ul><p></p><h2><strong>Наиболее распространённые ранние симптомы беременности</strong></h2><p>В первые дни после задержки или даже до неё перечисленные ниже признаки могут стать более заметными. Не у каждой женщины возникают все эти симптомы, но к самым распространённым относятся:</p><h3><strong>Чувствительность и увеличение груди</strong></h3><p>Одним из самых ранних и распространённых признаков беременности являются изменения груди. Под воздействием гормонов молочные железы набухают, становятся тяжелее и крайне чувствительными к прикосновениям.</p><ul><li><p><strong>Что вы можете почувствовать?</strong> Ареолы могут потемнеть, а вены — стать более заметными. Обычно эти ощущения выражены сильнее, чем болезненность груди при ПМС.</p></li></ul><p></p><h3><strong>Беспричинная усталость и слабость</strong></h3><p>Вам трудно просыпаться по утрам? Днём глаза сами закрываются? Резкое повышение уровня прогестерона словно переводит вас в «режим сна». Организм расходует много энергии на зарождение новой жизни, уровень сахара в крови и артериальное давление могут снижаться, из-за чего вы можете постоянно чувствовать усталость.</p><h3><strong>Утренняя тошнота (токсикоз)</strong></h3><p>Несмотря на название «утренняя», тошнота может возникать в любое время суток — утром, днём или ночью. У одних женщин это лишь лёгкая тошнота, у других — тяжёлое состояние, сопровождающееся рвотой. Обычно токсикоз начинается на 4-6-й неделях беременности, но при повышенной чувствительности организма может появиться раньше.</p><h3><strong>Повышенная чувствительность к запахам</strong></h3><p>Запах любимых духов вдруг стал для вас невыносимым? Или вы чувствуете у себя дома аромат блюда, которое готовят соседи? Повышение уровня эстрогена усиливает обоняние почти до уровня «суперспособности». Это часто напрямую связано с отсутствием аппетита и тошнотой.</p><h3><strong>Частое мочеиспускание</strong></h3><p>Во время беременности объём крови в организме увеличивается, поэтому почкам приходится перерабатывать больше жидкости. В результате потребность посещать туалет значительно возрастает. Обычно этот симптом появляется после 6-й недели, но у некоторых женщин из-за гормональных изменений он наблюдается раньше.</p><h2><strong>Психологические изменения: перепады настроения</strong></h2><p>Ещё минуту назад вы смеялись, а теперь вам без причины хочется плакать? Гормоны беременности влияют на нейромедиаторы головного мозга, вызывая эмоциональные колебания. Хотя это похоже на проявления ПМС, при беременности эмоции обычно бывают более сильными и внезапными. Совершенно нормально, если вы чувствуете раздражительность, ранимость или чрезмерную тревожность.</p><h2><strong>ПМС или беременность? Как отличить?</strong></h2><p>Признаки беременности часто путают с предменструальным синдромом (ПМС). Вот основные различия:</p><ul><li><p><strong>Кровотечение:</strong> При ПМС его не бывает, а при беременности возможно кратковременное «имплантационное кровотечение».</p></li><li><p><strong>Аппетит:</strong> При ПМС усиливается тяга к сладкому и солёному, а при беременности может возникнуть резкое отвращение к некоторым продуктам (например, к мясу или яйцам).</p></li><li><p><strong>Боль в животе:</strong> При ПМС боли обычно сильнее, а на ранних сроках беременности могут ощущаться лёгкое потягивание или покалывание.</p></li></ul><p></p><h2><strong>Можно ли быть уверенной на 100% без теста?</strong></h2><p>Короткий ответ: <strong>Нет.</strong></p><p>Все перечисленные выше признаки — усталость, болезненность груди и даже задержка — могут возникать и по другим причинам (стресс, гормональные нарушения, смена сезона, путешествие). А некоторые женщины даже при беременности не испытывают никаких симптомов на раннем сроке.</p><p>Сигналы организма лишь дают вам весомую «подсказку». Единственный научно обоснованный способ подтвердить ваши предположения — <strong>тест на беременность</strong>.</p><ul><li><p><strong>Домашние тесты (анализ мочи):</strong> Дают более точный результат через 1-2 дня после задержки менструации.</p></li><li><p><strong>Анализ крови (ХГЧ):</strong> Показывает наиболее точный результат через 7-10 дней после оплодотворения, то есть ещё до задержки менструации.</p></li></ul><p></p><p>Первые признаки беременности могут отличаться у разных женщин и даже при разных беременностях у одной и той же женщины. Если вы заметили у себя перечисленные симптомы:</p><ul><li><p><strong>Сохраняйте спокойствие:</strong> Гормоны стресса могут негативно влиять на ваш организм.</p></li><li><p><strong>Следите за питанием:</strong> Откажитесь от алкоголя и начните принимать фолиевую кислоту.</p></li><li><p><strong>Начните наблюдение:</strong> Используйте <strong>приложение Anacan</strong>, чтобы записывать свои симптомы. Умный трекер в нашем приложении поможет вам понять, являются ли изменения в организме нормальными.</p></li></ul><p>Если у вас задержка менструации или симптомы усиливаются, обязательно проконсультируйтесь с врачом. Помните: каждое новое ощущение ещё на один шаг приближает вас к долгожданной встрече.</p>') WHERE id = '8ac69e27-52fc-4ad6-af67-056deff4a903';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Грудное вскармливание: правила правильного прикладывания и способы увеличить количество молока'), excerpt_ru = COALESCE(excerpt_ru, 'Почему грудного молока бывает мало? Что есть, чтобы увеличить его количество? Правильные позы для кормления, питание кормящей мамы и советы, которые помогут избавиться от страха «моего молока недостаточно».'), content_ru = COALESCE(content_ru, 'Помните момент, когда впервые взяли малыша на руки? Эти крошечные ручки, ищущий взгляд... Природа всё предусмотрела: ваш организм производит для малыша идеальную пищу — **грудное молоко**.

Грудное молоко — не просто пища, но и первая защита малыша, подобная вакцинации. Оно содержит живые клетки, антитела и гормоны. Но признаем: грудное вскармливание не всегда с самого начала бывает таким лёгким и романтичным, как в фильмах. Новоиспечённых мам часто беспокоят вопросы: *«Правильно ли малыш захватывает грудь?», «Хватает ли ему моего молока?», «Почему мне больно?»*

В этой статье мы раскроем секреты успешного грудного вскармливания, рассмотрим научно обоснованные способы увеличить количество молока и выясним, насколько верен совет наших бабушек: «Пей сладкий чай, чтобы было молоко».

## 1. Правильное грудное вскармливание: всё начинается с «захвата»

Главное условие безболезненного и эффективного кормления — правильный захват груди малышом (**Latching**). Если во время кормления вы ощущаете сильную боль или на сосках появляются повреждения, значит, малыш захватывает грудь неправильно.

**Признаки правильного захвата:**

- **Широко открытый рот:** Рот малыша должен быть широко открыт (как «рыбий рот»), захватывая не только сосок, но и окружающую его тёмную область — ареолу.
- **Положение подбородка:** Подбородок малыша должен плотно касаться груди, а нос — оставаться свободным.
- **Губы:** Нижняя губа малыша должна быть вывернута наружу.
- **Звук:** Вы должны слышать, как малыш глотает, а не чмокает (чмоканье означает, что он заглатывает воздух).

> Совет: Перед кормлением выберите удобное место. Подложите подушки под спину и руку. Если вам неудобно, отток молока (окситоциновый рефлекс) может быть затруднён.
> 

## 2. Страх «у меня мало молока» и способы увеличить его количество

Многие мамы подозревают, что у них мало молока, и поспешно переходят на молочную смесь. Но помните: выработка молока работает по принципу **«Спрос и предложение»**. Чем чаще малыш сосёт грудь, тем чаще в мозг поступает сигнал «нужно больше молока» и тем больше молока вырабатывает организм.

**Самые эффективные способы увеличить количество молока:**

### Чаще кормите грудью

Кормите новорождённого не по часам, а по требованию. Кормление 8-12 раз в сутки (или чаще) — это нормально. Ночные кормления особенно важны, поскольку гормон, отвечающий за выработку молока (пролактин), активнее выделяется ночью.

### Контакт «кожа к коже» (Skin-to-skin)

Положите раздетого малыша (только в подгузнике) к себе на грудь и накройтесь одеялом. Такой контакт повышает уровень окситоцина и у вас, и у малыша, облегчая отток молока.

### Полностью опорожняйте грудь

Не перекладывайте малыша к другой груди, пока он не опорожнит первую. Молоко, которое малыш получает в конце кормления (**заднее молоко**), более жирное и питательное.

### Пейте достаточно воды

Грудное молоко на 87% состоит из воды. При обезвоживании его количество может уменьшиться. Во время каждого кормления держите рядом стакан воды.

## 3. Питание: продукты, способствующие выработке молока

Хотя наши бабушки советуют «есть халву и пить сладкий чай», сахар не увеличивает количество молока — он лишь способствует набору веса. К продуктам, стимулирующим лактацию (лактогонам), относятся:

- **Фенхель (Fennel) и тмин:** Чай из этих семян способствует выработке молока и уменьшает газообразование (колики) у малыша.
- **Овёс (Oatmeal):** Овсяная каша на завтрак — отличный выбор.
- **Грецкие орехи, фундук, миндаль:** Это источники Омега-3 и белка, способствующие повышению качества молока.
- **Финики:** Натуральный источник энергии и витаминов.
- **Зелёные листовые овощи:** Шпинат, укроп, петрушка.

## 4. Распространённые мифы о грудном вскармливании

> Миф: «Моё молоко жидкое, как вода, поэтому малыш не наедается».
Правда: Грудное молоко не бывает некачественным. Молоко, которое выделяется в начале кормления (переднее молоко), более жидкое, чтобы утолить жажду малыша. По мере кормления молоко становится более густым и жирным (заднее молоко). Поэтому не прекращайте кормление слишком рано.
> 

> Миф: «У меня маленькая грудь, поэтому молока будет мало».
Правда: Размер груди зависит от количества жировой ткани, а объём железистой ткани у всех женщин примерно одинаков. Даже с небольшой грудью можно выкормить двойню!
> 

> Миф: «Из-за стресса пропадает молоко».
Правда: Сильный стресс не прекращает выработку молока, но может затруднить его отток (рефлекс выделения молока). Когда вы успокоитесь и почувствуете запах своего малыша, молоко снова начнёт поступать.
> 

## Как понять, что малыш наедается?

Плач не всегда означает голод. Понять, что малыш получает достаточно молока, можно по двум показателям:

1. **Мокрые и грязные подгузники:** Если после 5-го дня жизни малыш мочится не менее 5-6 раз в сутки (подгузник становится тяжёлым), а его стул имеет жёлтый цвет.
2. **Прибавка в весе:** Малыш должен восстановить вес, потерянный в первую неделю жизни, к 10-14-му дню, а затем стабильно набирать вес.


Грудное вскармливание — процесс, требующий терпения и практики. Даже если в первые дни вам трудно, не сдавайтесь. Каждая капля грудного молока — драгоценный подарок вашему малышу. Если у вас возникают трудности, обратитесь к педиатру или консультанту по грудному вскармливанию.

Чтобы отмечать время кормлений, мокрые и грязные подгузники и сон малыша, используйте функцию **«Трекер малыша» в приложении Anacan**.') WHERE id = 'd4ab3b17-b307-43d7-a89e-46869dad48d4';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Гид по спокойному сну: как наладить режим сна малыша?'), excerpt_ru = COALESCE(excerpt_ru, 'Как наладить режим сна малыша? Научный гид о тёмной обстановке, борьбе с «переутомлением» и идеальных ритуалах сна — в Anacan'), content_ru = COALESCE(content_ru, '<p>«Когда мой малыш начнёт спать без пробуждений?» — вероятно, это самый первый вопрос, который каждая мама задаёт педиатру в первые месяцы. Недосып — это не просто усталость, а серьёзный фактор, напрямую влияющий на психологическое здоровье мамы, выработку грудного молока и формирование связи с малышом.</p><p>Помните: сон жизненно важен для физического роста малыша (гормон роста выделяется во сне), развития мозга и закрепления в памяти информации, полученной в течение дня. Наладить режим сна — не значит превратить малыша в робота. Это значит помочь ему настроить биологические часы организма (циркадный ритм). Когда же следует начинать этот процесс и какие практические шаги предпринять?</p><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776541619678-7lncxagqsbk.png"><h2>1. Когда начинать формировать режим сна?</h2><p>В период новорождённости (0-2 месяца) мозг малыша ещё не умеет различать день и ночь. Его сон состоит из периодов продолжительностью 40-50 минут, называемых «циклами сна» (sleep cycles), и в конце каждого цикла малыш часто просыпается. В этот период установить строгий режим невозможно, да это и не требуется.</p><p>С неврологической точки зрения биологические часы малыша (циркадный ритм) начинают формироваться примерно в <strong>6-8 недель</strong>. Именно с этого периода вы можете постепенно вводить ритуалы сна, помогая малышу научиться различать день и ночь. А начиная с 3-4 месяцев уже можно выстраивать более системный режим сна.</p><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776541645630-93ot5kb8f4l.png"><h2>2. Почему режим сна так важен?</h2><p>Режим нужен не только для удобства мамы, но и для эмоциональной безопасности малыша. Когда малыши знают, что и когда произойдёт, они чувствуют себя спокойнее и защищённее.</p><p>Регулярный режим сна:</p><ul><li><p>Посылает мозгу малыша сигналы о том, что пора успокоиться.</p></li><li><p>Снижает риск «переутомления» (overtiredness): у уставшего малыша выделяется гормон кортизол, из-за чего он не может заснуть.</p></li><li><p>Позволяет маме планировать своё время и отдыхать.</p></li></ul><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776542044502-pfjf2g827s.png"><h2>3. Идеальная обстановка и ритуалы сна для малыша</h2><p>Правильная обстановка и ритуалы перед сном (wind-down routines) — это основа, помогающая малышу легче заснуть.</p><ul><li><p><strong>«Ритуалы сна» (подготовка ко сну):</strong> За 20-30 минут до сна выполняйте успокаивающие действия, каждый раз повторяя их в одной и той же последовательности. Например: тёплая ванна, лёгкий массаж, пеленание в муслиновую пелёнку, кормление грудью (или смесью) при приглушённом свете, тихая колыбельная или сказка. Такая последовательность подаёт мозгу малыша сигнал: «Сейчас время спать».</p></li><li><p><strong>Тёмная обстановка:</strong> Для ночного сна очень важно, чтобы в комнате было <strong>совершенно темно</strong>. Темнота стимулирует выработку гормона сна — <em>мелатонина</em>. Затемнение комнаты во время дневного сна также помогает увеличить его продолжительность.</p></li><li><p><strong>Тишина или «белый шум» (White noise):</strong> В полной тишине малыши могут легко просыпаться. Устройства или игрушки с белым шумом заглушают посторонние звуки с улицы и успокаивают малыша, напоминая ему шум, который он слышал в утробе мамы.</p></li><li><p><strong>Температура:</strong> Для качественного сна важно поддерживать в комнате температуру <strong>18-22 градуса</strong> и не одевать малыша слишком тепло, чтобы он не потел.</p></li></ul><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776542065349-7lpc7tvxki.png"><h2>4. Понятие «окно сна» и борьба с «переутомлением»</h2><p>Чтобы понять, почему ваш малыш не может заснуть или часто просыпается, важно знать, что такое «окно сна».</p><p><strong>«Окно сна» (Awake window)</strong> — это оптимальный промежуток времени, в течение которого малыш может бодрствовать, а затем заснуть, не переутомившись. Например:</p><ul><li><p>У новорождённых (0-1 месяц): 45-60 минут.</p></li><li><p>В 3-4 месяца: 1.5 - 2 часа.</p></li><li><p>В 6 месяцев: 2.5 - 3 часа.</p></li></ul><p>Если вы пропустите окно сна малыша, он войдёт в состояние <strong>«переутомления»</strong> (overtired). В этот момент организм малыша выделяет гормоны стресса — кортизол и адреналин. В результате малыш становится беспокойным, плачет, не хочет слезать с рук, и вам приходится часами укладывать его спать.</p><p>Поэтому при формировании режима ориентируйтесь не на часы, а на продолжительность бодрствования малыша и сигналы сонливости: он трёт глаза, тянет себя за ухо, смотрит вдаль или зевает.</p><img src="https://tntbjulojatnrqmylorp.supabase.co/storage/v1/object/public/assets/editor/1776542091452-0k76t7luiehc.png"><h2>5. Отслеживание режима сна с Anacan</h2><p>Помните, что формирование режима сна — это процесс, требующий времени и терпения. Записывая продолжительность сна малыша в разделе «Отслеживание сна» приложения <strong>Anacan</strong>, вы сможете наблюдать за его индивидуальным режимом и легче пройти этот период. Кроме того, вы сможете предоставить педиатру точные, научно обоснованные данные о развитии малыша. Anacan всегда рядом с вами!</p>') WHERE id = 'd324c599-b1a2-44da-b6ca-c70a350d68d6';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Уход за новорождённым: всё, что нужно знать в первые дни (Купание, уход за пупком)'), excerpt_ru = COALESCE(excerpt_ru, 'Первые дни дома после возвращения из роддома: как ухаживать за пупком малыша? Правила первого купания, смена подгузника и уход за кожей. Пошаговая инструкция для молодых мам.'), content_ru = COALESCE(content_ru, 'Момент, когда вы выходите из роддома и входите домой с этим маленьким «свёртком» на руках... Это одновременно и самый счастливый, и самый волнительный момент в мире. В роддоме всё делали медсёстры, но что теперь?

Малыш кажется таким маленьким и хрупким, что вы боитесь даже прикоснуться к нему. В голове кружатся вопросы: *«Не поврежу ли я пупок?», «Не слишком ли горячая вода?», «Правильно ли я одела малыша?»*

Дорогие мама и папа, сохраняйте спокойствие. Малыши гораздо выносливее, чем вы думаете. В этой статье мы простым и понятным языком расскажем об основных навыках, которые особенно пригодятся вам в первые дни: гигиене, купании и уходе за пупком.

## 1. Уход за пупком: не бойтесь прикасаться!

Остаток пуповины у новорождённого больше всего беспокоит родителей. Обычно он высыхает и отпадает самостоятельно через 10-21 день после рождения. До этого момента главное правило — **«Содержать в чистоте и сухости»**.

### Золотые правила:

- **Не обрабатывайте спиртом и зелёнкой (бриллиантовым зелёным):** современная педиатрия не рекомендует этого делать. Эти средства могут вызвать ожог кожи и замедлить заживление. Достаточно аккуратно протирать область кипячёной водой и стерильной марлей.
- **Застёгивайте подгузник ниже пупка:** подверните край подгузника так, чтобы пупок оставался открытым и к нему поступал воздух. Контакт с воздухом ускоряет высыхание.
- **Купать можно:** малыша можно купать до того, как отпадёт остаток пуповины, но после купания эту область необходимо осторожно и полностью высушить.

### Тревожные признаки (Когда нужно сообщить врачу?):

- Вокруг пупка появились покраснение и отёк.
- Появились выделения с неприятным запахом или гной.
- Малыш плачет при прикосновении к области пупка.

## 2. Первое купание: знакомство с водой

Нет необходимости купать малыша каждый день (достаточно 2-3 раз в неделю), однако в нашей культуре ежедневное купание, особенно вечером перед сном, является традицией и помогает успокоить малыша.

### Подготовка:

Температура в комнате должна составлять **24-26°C**, а температура воды — **37°C** (температура тела). Чтобы проверить воду, опустите в неё локоть: вода не должна казаться ни горячей, ни холодной.

### Шаг за шагом:

1. **Безопасность:** положите всё необходимое (полотенце, мыло, подгузник) так, чтобы оно было у вас под рукой. Никогда не оставляйте малыша одного в воде!
2. **Не спешите:** не погружайте малыша в воду резко. Сначала опустите ножки, а затем тело. Поддерживайте его голову и шею рукой.
3. **Лицо и голова:** умойте лицо чистой водой без мыла. Протирайте глаза по направлению от внутреннего уголка к внешнему. Вымойте голову специальным детским шампунем, который не щиплет глаза.
4. **Тело:** не забудьте промыть подмышки, складочки на шее и участки между пальчиками.

> Миф: «До сорокового дня после рождения в воду нужно добавлять соль».
Правда: солёная вода может пересушить нежную кожу малыша и вызвать зуд. Лучше всего использовать обычную водопроводную воду (если она чистая) или кипячёную воду.
> 

## 3. Смена подгузника и профилактика опрелостей

Кожа малыша очень чувствительна. Если влага и кал долго соприкасаются с кожей, возникает пелёночный дерматит — «опрелости».

- **Меняйте чаще:** меняйте подгузник каждые 2-3 часа или сразу после каждого стула.
- **Подмывайте, а не вытирайте:** по возможности вместо влажных салфеток подмывайте малыша под проточной водой. Салфетки, даже самые дорогие, могут вызвать раздражение.
- **Воздушные ванны:** прежде чем надеть новый подгузник, оставьте малыша без него на 5-10 минут, чтобы кожа подышала.
- **Крем:** используйте защитные кремы с цинком (Sudocrem, Desitin и т. п.). Присыпки (тальк) больше не рекомендуются, поскольку их частицы могут попасть в дыхательные пути.

## 4. Уход за кожей: шелушение и высыпания

В первые недели вы можете заметить шелушение кожи или небольшие прыщики у малыша.

- **Шелушение:** это нормально. После 9 месяцев в водной среде кожа малыша начинает контактировать с воздухом. Можно наносить увлажняющее детское масло или лосьон.
- **Гормональные высыпания:** на лице могут появиться мелкие красные высыпания (акне новорождённых). Они связаны с материнскими гормонами и проходят самостоятельно, без лечения. Не выдавливайте их!

## 5. Уши, нос и ногти

- **Уши:** никогда не вводите ватную палочку внутрь уха! Протирайте только наружную часть.
- **Нос:** заложенность носа мешает малышу сосать. Нос можно очистить с помощью капель с морской водой и аспиратора.
- **Ногти:** малыши часто царапают себе лицо. Подстригайте ногти специальными детскими ножницами, когда малыш спит. В первые дни можно надевать ему рукавички-царапки.


Первые дни могут показаться трудными, но поверьте: совсем скоро вы освоитесь. Именно вы лучше всех знаете своего малыша. Доверяйте своим инстинктам и не стесняйтесь просить о помощи — у супруга или своей мамы.

Чтобы следить за режимом сна, питанием и прибавкой веса малыша, скачайте **приложение Anacan**. Мы рядом с вами в течение первого года!') WHERE id = '5737b404-9709-4b83-ab5c-0bc9f8b46a7f';
UPDATE public.blog_posts SET title_ru = COALESCE(title_ru, 'Перелёты во время беременности: до какой недели разрешено летать?'), excerpt_ru = COALESCE(excerpt_ru, 'Опасно ли летать на самолёте во время беременности? До какой недели авиакомпании (AZAL, THY) допускают к перелёту? Справка "Fit to Fly", сканеры в аэропорту и золотые правила профилактики тромбоза во время полёта.'), content_ru = COALESCE(content_ru, 'Беременность не означает, что вы должны полностью изменить свой образ жизни. Будь то деловая поездка или последний отдых перед рождением малыша ("Babymoon"), желание путешествовать на самолёте совершенно нормально. Однако перед тем как нажать кнопку "Подтвердить" при покупке билета, у вас могут возникнуть сомнения: *"Не навредит ли перепад давления малышу?", "Что будет, если схватки начнутся в воздухе?"*.

Самолёт — один из самых безопасных видов транспорта для беременных, однако есть определённые "но". В этой статье мы собрали для вас правила авиакомпаний, рекомендации врачей и секреты комфортного путешествия над облаками.

## Главный вопрос: вредят ли давление и радиация малышу?

Многие будущие мамы опасаются изменений давления в салоне и космической радиации.

- **Давление в салоне:** Современные пассажирские самолёты герметичны, а давление внутри регулируется. Хотя оно соответствует высоте немного выше уровня моря, при нормально протекающей беременности это не оказывает негативного влияния на снабжение малыша кислородом.
- **Радиация:** Поскольку самолёт летит на большой высоте, уровень космической радиации немного выше, чем на земле. Однако при редких перелётах эта доза **крайне мала** и не вредит плоду. (Риск существует только для бортпроводниц и пилотов, которые летают каждый день).

## "Золотой период" для перелётов: 2-й триместр

Врачи считают, что наиболее подходящее время для путешествий — период между **14-й и 28-й неделями** беременности (второй триместр).

- **Почему?** Токсикоз и слабость первого триместра уже позади, а риск выкидыша значительно снизился. При этом живот ещё не настолько большой, чтобы мешать двигаться, а риск преждевременных родов остаётся низким.

## Правила авиакомпаний: кому и когда разрешено летать?

Хотя правила могут различаться в зависимости от авиакомпании (например, AZAL, Turkish Airlines), международные стандарты (IATA) обычно таковы:

### При одноплодной беременности (один малыш):

- **До 28-й недели:** Справка от врача не требуется, и вы можете спокойно летать.
- **Между 28-35-й неделями:** Для допуска к перелёту требуется **"Справка о пригодности к перелёту" (Fit to Fly)** от врача. В справке должны быть указаны срок беременности и формулировка "противопоказаний к перелёту нет" (обычно её необходимо получить в течение 7 дней до вылета).
- **После 36-й недели:** Даже при наличии разрешения врача вас, как правило, **не допускают к перелёту**. Причина проста: ни одна авиакомпания не хочет брать на себя риск родов на борту.

### При беременности двойней (многоплодной беременности):

Допустимые сроки короче. Обычно перелёты запрещены **после 32-й недели**.

> Важно: Перед покупкой билета обязательно ознакомьтесь с разделом "Беременные пассажиры" на официальном сайте выбранной авиакомпании.
> 

## Сканеры в аэропорту: можно ли через них проходить?

Досмотр в аэропорту — ещё один повод для беспокойства.

- **Металлодетекторы (рамки):** Они работают с помощью магнитного поля и совершенно безопасны.
- **Сканеры тела (Millimeter wave):** Они не излучают радиацию, работают с помощью радиоволн и считаются безопасными.
- **Рентген (X-Ray):** Он предназначен только для багажа! Никогда не опускайте руку и не помещайте другие части тела внутрь ленты, по которой проходят сумки.

Если вы всё же беспокоитесь, сообщите сотруднику о беременности и попросите провести ручной досмотр.

## Самый большой риск: тромбоз глубоких вен (ТГВ)

Во время беременности свёртываемость крови повышается. Длительное неподвижное сидение в самолёте увеличивает риск образования сгустка крови (тромба) в ногах.

**Как защитить себя?**

1. **Компрессионные чулки:** Проконсультируйтесь с врачом и наденьте противоварикозные чулки.
2. **Движение:** Каждый час вставайте и ходите по салону.
3. **Гимнастика на месте:** Сидя вращайте стопами, поднимайте и опускайте пятки.
4. **Питьевой режим:** Воздух в самолёте сухой. Пейте много воды, чтобы предотвратить сгущение крови. Откажитесь от кофе и чая.

## Советы для комфортного перелёта

- **Выбор места:** Выберите место у прохода (Aisle seat). Так вам будет удобнее часто ходить в туалет и разминать ноги.
- **Ремень безопасности:** Застёгивайте ремень не поверх живота, а **под ним** (на уровне тазовых костей).
- **Страховка:** Уточните, покрывает ли ваша туристическая страховка расходы, связанные с беременностью.

## Кому нельзя летать? (Противопоказания)

В следующих случаях врач не разрешит вам лететь:

- Если диагностировано предлежание плаценты.
- Если существует риск преэклампсии (высокого артериального давления).
- Если укорочена шейка матки или существует угроза преждевременных родов.
- Если есть подозрение на отхождение вод или кровотечение.
- При тяжёлой анемии (если уровень гемоглобина очень низкий).


Путешествовать во время беременности можно и даже нужно (после рождения малыша найти для этого время будет непросто!). Просто вам потребуется немного больше планирования и осторожности.

Перед полётом обязательно проконсультируйтесь с врачом, получите справку "Fit to Fly" и точно рассчитайте срок беременности в **приложении Anacan**, чтобы не столкнуться с неожиданностями в аэропорту. Счастливого пути!') WHERE id = '8335f021-49ee-419f-a38a-123aadea6701';
