UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Super Grain Bowl — салат с киноа'), description_ru = COALESCE(description_ru, 'Настоящая белковая бомба. Содержит все незаменимые аминокислоты и повышает питательную ценность грудного молока.'), category_ru = COALESCE(category_ru, 'обед'), tags_ru = COALESCE(tags_ru, ARRAY['послеродовой_период']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Киноа: половина стакана (в готовом виде)","Чёрная фасоль или нут: половина стакана","Авокадо: половина","Петрушка: 1 пучок","Лимонный сок, оливковое масло"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Промойте киноа, варите 15 минут, затем слейте воду","Добавьте варёную фасоль или нут","Нарежьте авокадо кубиками","Смешайте с петрушкой, лимонным соком и оливковым маслом","Подавайте холодным или комнатной температуры"]'::jsonb) WHERE id = '971c317e-b7ac-4733-b72a-ef93a65eb1b6';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Первая зелень — пюре из кабачка'), description_ru = COALESCE(description_ru, 'Самый лёгкий вариант для начала прикорма, щадящий пищеварительную систему малыша (6 месяцев+)'), category_ru = COALESCE(category_ru, 'детское_питание'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Кабачок — 1 небольшой","Оливковое масло — 1 чайная ложка","Грудное молоко/смесь"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Приготовьте кабачок на пару","Измельчите в блендере","Добавьте грудное молоко и оливковое масло"]'::jsonb) WHERE id = '12f0782c-f0f2-4ba6-a173-dbb482071e15';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Оранжевое сияние — морковный салат'), description_ru = COALESCE(description_ru, 'Богатый кальцием союз моркови и тахини. Бета-каротин и кальций повышают питательную ценность грудного молока.'), category_ru = COALESCE(category_ru, 'ужин'), ingredients_ru = COALESCE(ingredients_ru, '["Морковь: 2 штуки (натёртые)","Грецкие орехи: 1 горсть (измельчённые)","Тахини (кунжутная паста): 1 столовая ложка","Лимонный сок, оливковое масло","Укроп: несколько веточек"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Натрите морковь","Измельчите и добавьте грецкие орехи","Мелко нарежьте укроп","Приготовьте соус из тахини, лимонного сока и оливкового масла","Всё перемешайте и подавайте — этот салат полон витаминов"]'::jsonb) WHERE id = 'ee7e5b2c-3005-40bc-948c-9e7d5600cfdc';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Компот «Нектар жизни»'), description_ru = COALESCE(description_ru, 'Натуральный напиток из сухофруктов без добавления сахара. Грудное молоко на 80% состоит из воды — этот компот хорошо утоляет жажду.'), category_ru = COALESCE(category_ru, 'полезные_напитки'), ingredients_ru = COALESCE(ingredients_ru, '["Курага (сушёные абрикосы): 5-6 штук","Чернослив: 3-4 штуки","Яблоко (сушёное или свежее): нарезанное ломтиками","Вода: 1.5 литра"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Промойте сухофрукты","Положите их в 1.5 литра воды и доведите до кипения","После закипания варите на слабом огне 20 минут","Не добавляйте сахар — естественной сладости фруктов достаточно","Пейте охлаждённым и в достаточном количестве в течение дня"]'::jsonb) WHERE id = '50c1c324-2182-4a8b-9fa1-e6567601c2d3';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Золотое яблоко — пюре из запечённого яблока'), description_ru = COALESCE(description_ru, 'Приготовленное яблоко не вызывает газообразования и очень нравится малышам (6 месяцев+)'), category_ru = COALESCE(category_ru, 'детское_питание'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Яблоко — 1 штука","Вода"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Очистите яблоко и нарежьте ломтиками","Приготовьте на пару","Измельчите в блендере"]'::jsonb) WHERE id = 'd3d9ab59-ad73-4c09-ad5f-3b3fedca7488';
