UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Жемчужина океана — лосось со спаржей'), description_ru = COALESCE(description_ru, 'Классический дуэт, который увлажняет кожу изнутри и помогает уменьшить отёки.

