UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Фалафель в духовке'), description_ru = COALESCE(description_ru, 'Запечённое в духовке, богатое клетчаткой и хрустящее восточное блюдо для тех, кто избегает жареного.

