UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Зелёное чудо — кюфта с укропом'), description_ru = COALESCE(description_ru, 'Один из самых известных секретов азербайджанской кухни для поддержки лактации — много укропа!'), category_ru = COALESCE(category_ru, 'обед'), ingredients_ru = COALESCE(ingredients_ru, '["Фарш (говяжий или куриный): 300 qr","Рис: половина стакана","Укроп: 2 больших пучка","Картофель: 2 шт.","Лук: 1 шт.","Соль, перец"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смешайте фарш, промытый рис и половину мелко нарезанного укропа","Добавьте соль и перец, сформируйте кюфту","Положите нарезанные картофель и лук в кипящую воду","Через 5 dəq добавьте кюфту и варите на слабом огне 25-30 dəq","Незадолго до готовности мелко нарежьте оставшийся укроп и щедро добавьте в суп"]'::jsonb) WHERE id = 'b8788575-43f0-4748-a08b-a02e6044caa7';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Янтарный поток — чай из пажитника'), description_ru = COALESCE(description_ru, 'Пажитник (Fenugreek) традиционно используется для поддержки лактации и может стимулировать выработку пролактина.'), category_ru = COALESCE(category_ru, 'полезные_напитки'), ingredients_ru = COALESCE(ingredients_ru, '["Семена пажитника (Fenugreek): 1 чайная ложка","Вода: 2 стакана","Мёд: 1 чайная ложка (по желанию)","Лимон: несколько капель"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Слегка обжарьте семена пажитника на сухой сковороде в течение 1-2 минут (не допускайте подгорания)","Добавьте в кипящую воду","Настаивайте 10 минут, затем процедите","По желанию добавьте мёд и лимон","Пейте по 2-3 чашки в день — эффект может стать заметен через 24-48 часов"]'::jsonb) WHERE id = '52d3741b-ea80-45a2-99fd-beda7e7b6c4a';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Утренний боул с матча'), description_ru = COALESCE(description_ru, 'Антиоксидантный вариант для тех, кто хочет взбодриться без кофе и поддержать обмен веществ.

Польза: чай матча поддерживает обмен веществ и здоровье кожи. В отличие от кофе, он не даёт резкого прилива энергии, а помогает сохранять бодрость в течение дня'), category_ru = COALESCE(category_ru, 'завтрак'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Замороженный банан: 1 шт.","Порошок матча: 1 чайная ложка","Шпинат: 1 небольшая горсть","Миндальное молоко: половина стакана","Для украшения: кокосовая стружка, миндаль, ломтики киви."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Взбейте банан, матча, шпинат и молоко в блендере до консистенции густого смузи. Перелейте в миску и украсьте орехами и киви."]'::jsonb) WHERE id = '8c4792f6-0abc-4597-99d1-ff981dc2a340';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Шот «Сладкие сны»'), description_ru = COALESCE(description_ru, 'Для уменьшения мышечных спазмов и напряжения'), category_ru = COALESCE(category_ru, 'полезные_напитки'), ingredients_ru = COALESCE(ingredients_ru, '["Миндаль — 5 шт. (замоченных)","Банан — четверть","Какао — половина чайной ложки","Вода — 2 столовые ложки"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Очистите миндаль","Взбейте все ингредиенты в блендере до жидкой консистенции"]'::jsonb) WHERE id = '13b7591b-479c-457d-ab27-09785681c532';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Питательный крем — авокадо и банан'), description_ru = COALESCE(description_ru, 'Источник полезных жиров для развития мозга, не требует приготовления (7 месяцев+)'), category_ru = COALESCE(category_ru, 'детское_питание'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание', 'богато_витаминами']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Авокадо — половина","Банан — половина"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разомните оба ингредиента вилкой","Оставьте небольшие кусочки"]'::jsonb) WHERE id = '2b374b35-8810-48b4-a990-d7b6c19bcd99';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Первый белок — курица с овощами'), description_ru = COALESCE(description_ru, 'Первое знакомство малыша с мясом (7-8 месяцев)'), category_ru = COALESCE(category_ru, 'детское_питание'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Куриная грудка — 40 qr","Брокколи — 3 соцветия","Оливковое масло"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите мясо, первый бульон слейте","Добавьте овощи и варите до готовности","Измельчите всё вместе в блендере"]'::jsonb) WHERE id = 'f7f4a9f1-a670-4aa2-bc79-2ba16bd08e45';
