UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пицца из цветной капусты'), description_ru = COALESCE(description_ru, 'Чтобы наслаждаться пиццей без угрызений совести, глютена и теста.

Польза: цветная капуста богата фитонутриентами и способствует очищению печени. Такая пицца совсем не вызывает вздутия живота и изжоги.'), category_ru = COALESCE(category_ru, 'ужин'), ingredients_ru = COALESCE(ingredients_ru, '["Цветная капуста: половина кочана (натереть и полностью отжать сок)","Яйцо: 1 шт.","Сыр (тёртый): 3 столовые ложки (для основы)","Для начинки: томатная паста, ломтики помидора, сыр, базилик."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смешайте натёртую цветную капусту с яйцом и сыром, выложите на противень и сформируйте основу для пиццы. Выпекайте при 200 градусах 15 минут (до золотистой корочки). Затем достаньте, выложите сверху соус и остальные ингредиенты и выпекайте ещё 5 минут, пока сыр не расплавится."]'::jsonb) WHERE id = 'e3dad099-6f8a-4e3c-8dfa-2922158c70b6';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тёплый салат с грибами и шпинатом'), description_ru = COALESCE(description_ru, 'Тёплый, сытный салат с насыщенным ароматом грибов для вечеров, когда не хочется есть мясо.

Польза: содержащийся в шпинате магний расслабляет мышцы, а грибы богаты витамином D и витаминами группы B, которые укрепляют иммунитет.'), category_ru = COALESCE(category_ru, 'ужин'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Шампиньоны или вешенки: 150 г (нарезанные)","Молодой шпинат: 2-3 горсти (сырой)","Грецкие орехи: 1 горсть","Бальзамический уксус, оливковое масло, чеснок (немного)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обжарьте грибы с одним зубчиком чеснока в небольшом количестве масла до золотистого цвета. Выложите шпинат в миску. Добавьте горячие грибы к шпинату (под воздействием тепла шпинат слегка размягчится). Посыпьте грецкими орехами и сбрызните бальзамическим уксусом."]'::jsonb) WHERE id = 'cc18259a-201a-4dd4-83bd-d60fc14dccba';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Спагетти из кабачков с чечевицей'), description_ru = COALESCE(description_ru, 'Имитация пасты, богатая растительным белком, которая поможет забыть о тоске по спагетти.

Польза: благодаря кабачкам вы получаете минимум углеводов, а чечевица обеспечивает организм растительным железом и клетчаткой, облегчая пищеварение.'), category_ru = COALESCE(category_ru, 'ужин'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Кабачки: 2 шт. (нарезанные как спагетти)","Красная чечевица: половина стакана (отварная)","Помидор, лук, чеснок (для соуса)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Приготовьте из лука и помидора соус в стиле «Болоньезе» и добавьте в него готовую чечевицу. Обжарьте кабачки на сковороде в течение 2 минут, выложите на тарелку и щедро полейте чечевичным соусом."]'::jsonb) WHERE id = 'a5b41661-394b-4403-8c11-ef8c670867ac';
