UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Креветки с чесноком и кабачками'), description_ru = COALESCE(description_ru, 'Изысканное блюдо из морепродуктов ресторанного качества, но почти без калорий.

Польза: креветки богаты цинком и йодом, которые укрепляют волосы и ногти. Это очень лёгкое блюдо, поэтому оно идеально подходит для ужина.'), category_ru = COALESCE(category_ru, 'ужин'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Креветки (очищенные): 150 г","Кабачки: 2 шт. (нарезанные как спагетти)","Смесь сливочного масла (немного) и оливкового масла.","Чеснок: 2 зубчика (измельчённые), хлопья красного перца."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разогрейте на сковороде масло с чесноком, добавьте креветки и обжаривайте до розового цвета (всего 3-4 минуты). Добавьте кабачки и обжаривайте ещё 2 минуты. Сбрызните лимонным соком и сразу подавайте."]'::jsonb) WHERE id = '71d8c222-1035-4fd0-929b-23c2b485af16';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Лавандовое молоко'), description_ru = COALESCE(description_ru, 'Волшебный напиток, который снимает стресс после напряжённого дня и дарит крепкий сон.

