UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Холодный протеиновый шейк с какао'), description_ru = COALESCE(description_ru, 'Идеально подходит для восстановления мышц после тренировки и надолго дарит чувство сытости.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), ingredients_ru = COALESCE(ingredients_ru, '["1 столовая ложка какао, 1 замороженный банан, 1 столовая ложка арахисовой пасты, 1 стакан холодного молока, лёд."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Взбейте все ингредиенты в блендере до консистенции густого шейка."]'::jsonb) WHERE id = 'fff46867-aa41-4bc9-8647-1346ba044359';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Хрустящие кусочки с киноа и шоколадом'), description_ru = COALESCE(description_ru, 'Самый хрустящий и полезный ответ на тягу к шоколаду во время ПМС — периода перед менструацией.

Польза: тёмный шоколад богат магнием, который уменьшает спазмы и напряжение, а воздушная киноа служит источником белка и помогает поддерживать стабильный уровень сахара в крови.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Тёмный шоколад (не менее 70% какао): 100 г","Воздушная киноа (или овсяные хлопья): 1 стакан","Морская соль: совсем немного (для посыпки)"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Растопите шоколад на водяной бане. Добавьте киноа и тщательно перемешайте. Ложкой выложите небольшие порции на пергаментную бумагу. Посыпьте морской солью и оставьте в холодильнике на 20 минут до застывания."]'::jsonb) WHERE id = 'b3153614-fcee-47f5-887f-a9f21df0723d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тарт с какао и авокадо'), description_ru = COALESCE(description_ru, 'Невероятно полезная версия шоколадного тарта без выпечки, о составе которой никто не догадается.

Польза: полезные жиры авокадо необходимы для синтеза женских гормонов. Какао, в свою очередь, стимулирует выработку эндорфинов — гормонов счастья.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), ingredients_ru = COALESCE(ingredients_ru, '["Для основы: 1 стакан грецких орехов, 10 фиников.","Для крема: 2 спелых авокадо, полстакана какао без сахара, 4 столовые ложки мёда или пекмеза."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Измельчите грецкие орехи и финики в блендере, затем распределите массу по дну формы для тарта. Для крема взбейте в блендере авокадо, какао и мёд до совершенно гладкой, шелковистой консистенции. Распределите крем по основе и поставьте в холодильник на 2 часа."]'::jsonb) WHERE id = '1b665124-a619-4ee4-9dce-a48ced0f8106';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Финики с арахисовой пастой'), description_ru = COALESCE(description_ru, 'Моментально заряжающий энергией перекус, который по вкусу напоминает настоящую шоколадную конфету с карамелью.

Польза: полностью утоляет тягу к рафинированному сахару. Арахисовая паста содержит белок и полезные жиры, благодаря чему надолго насыщает.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Финики Medjool (крупные, мягкие): 5-6 штук","Арахисовая паста без сахара: 2 столовые ложки","Тёмный шоколад (растопленный)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разрежьте финики вдоль и удалите косточки. Наполните их арахисовой пастой. Окуните финики наполовину в растопленный тёмный шоколад и поставьте в холодильник до застывания."]'::jsonb) WHERE id = '23124658-0378-42aa-b696-d264cdef885d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Кешью-чизкейк с клубникой'), description_ru = COALESCE(description_ru, 'Великолепный «Raw Vegan» чизкейк без молочных продуктов, муки и сахара.

