UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пюре из батата и яблока (6 месяцев+)'), description_ru = COALESCE(description_ru, 'Учитывая любовь малышей к сладким вкусам, это блюдо наверняка станет одним из любимых вариантов первого прикорма.

