UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Овсяный флэт уайт с корицей'), description_ru = COALESCE(description_ru, 'Лёгкий и ароматный кофе, не вызывающий резкого повышения уровня сахара в крови (инсулина).'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['general', 'milk_boost']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["1 порция (shot) эспрессо, половина стакана вспененного овсяного молока, 1 чайная ложка молотой корицы."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Добавьте к эспрессо горячее овсяное молоко с густой пеной и щедро посыпьте корицей."]'::jsonb) WHERE id = 'a3480015-30ca-4f9a-b8de-a642fd9a639c';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пюре из авокадо и яйца
(8 месяцев+)'), description_ru = COALESCE(description_ru, 'Натуральное питательное сочетание, которое не требует приготовления (кроме яйца) и облегчает мамам утренние хлопоты.

