UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Шарики с миндалём, льном и чиа'), description_ru = COALESCE(description_ru, 'Хрустящие энергетические шарики без выпечки — отличный вариант перед тренировкой или к кофе.

