UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Миндальные кето-кексы'), description_ru = COALESCE(description_ru, 'Кексы без углеводов для тех, кто хочет чувствовать лёгкость, словно паря в облаках.

