UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Греческие сувлаки и дзадзики'), description_ru = COALESCE(description_ru, 'Король средиземноморской диеты: чистый белок, пробиотики и полезные жиры.

