UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Японский мисо-суп'), description_ru = COALESCE(description_ru, 'Лёгкий ферментированный суп, который японцы едят утром или вечером и считают одним из секретов долголетия.

