UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Ленивая овсянка с грецкими орехами и бананом'), description_ru = COALESCE(description_ru, 'Идеальный прохладный и лёгкий вариант для тех, кого по утрам беспокоит тошнота'), category_ru = COALESCE(category_ru, 'завтрак'), ingredients_ru = COALESCE(ingredients_ru, '["Овсяные хлопья - 4 столовые ложки","Молоко - 1 стакан","Банан - половина","Грецкие орехи - 2 шт.","Мёд - 1 чайная ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["С вечера смешайте овсяные хлопья, молоко и мёд","Поставьте в холодильник","Утром добавьте банан и грецкие орехи"]'::jsonb) WHERE id = 'ae635663-e33c-479a-970a-94bd85e39010';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Слоёная запеканка из баклажанов с сыром'), description_ru = COALESCE(description_ru, 'Лёгкая низкоуглеводная альтернатива лазанье'), category_ru = COALESCE(category_ru, 'ужин'), ingredients_ru = COALESCE(ingredients_ru, '["Баклажаны - 2 шт.","Помидоры - 2 шт.","Белый сыр - 60 qr","Базилик"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Тонко нарежьте баклажаны и слегка запеките их в духовке","Добавьте сыр, помидоры и базилик","Запекайте в духовке, пока сыр не расплавится"]'::jsonb) WHERE id = 'c940ec18-0208-46aa-8361-f2f2f659b141';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Запечённые персики с корицей'), description_ru = COALESCE(description_ru, 'Очень лёгкий десерт, напоминающий мороженое, но содержащий совсем мало калорий.

Польза: Персики богаты клетчаткой, которая поддерживает пищеварение, а корица может способствовать поддержанию нормального уровня сахара в крови.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), ingredients_ru = COALESCE(ingredients_ru, '["Персики: 2 шт. (разрезанные пополам, без косточек)","Корица: 1 чайная ложка","Грецкие орехи или орехи пекан: измельчённые","Густой йогурт (для подачи)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Выложите половинки персиков в форму для запекания, посыпьте их корицей и орехами. Запекайте при 180 градусах в течение 15-20 минут, пока они не станут мягкими. Подавайте тёплыми, положив в центр по ложке густого йогурта."]'::jsonb) WHERE id = 'e7b8a04c-a4fa-4769-bbd9-6735976b643a';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тыква с кокосовым молоком
(8 месяцев+)'), description_ru = COALESCE(description_ru, 'Первое знакомство малыша с необычными тропическими вкусами. Блюдо обладает нежной, шелковистой текстурой.

Польза: Тыква богата витамином A, важным для зрения. Кулинарное кокосовое молоко придаёт блюду кремовую текстуру и содержит растительные жиры, но не заменяет грудное молоко или детскую смесь.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Тыква: 1 ломтик (очищенный от кожуры и нарезанный кубиками)","Кокосовое молоко (не питьевое из упаковки, а густое кулинарное): 2 столовые ложки."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Готовьте тыкву на пару, пока она не станет мягкой. Добавьте кокосовое молоко и измельчите блендером. Получится очень сытный и вкусный суп."]'::jsonb) WHERE id = 'a8859019-9d72-40f8-8956-b03d1cfb1e34';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Шарики из брокколи с сыром(1 год+)'), description_ru = COALESCE(description_ru, 'Самый хрустящий и увлекательный способ помочь малышу полюбить брокколи.

