UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Безмучные панкейки с бананом и овсянкой'), description_ru = COALESCE(description_ru, 'Благодаря высокому содержанию клетчатки улучшают пищеварение, а банан служит источником калия'), category_ru = COALESCE(category_ru, 'завтрак'), ingredients_ru = COALESCE(ingredients_ru, '["Яйца - 2 шт.","Банан - 1 шт.","Овсяные хлопья - половина стакана","Корица - по вкусу"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разомните банан","Добавьте яйца и взбейте","Добавьте овсяную муку и корицу","Обжарьте на сковороде с обеих сторон"]'::jsonb) WHERE id = '1dc5ff7a-9167-45eb-a742-f8830d930c68';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Ленивые голубцы в духовке'), description_ru = COALESCE(description_ru, 'Блюдо не обжаривается, поэтому не вызывает изжогу, а богатые клетчаткой овощи облегчают пищеварение'), category_ru = COALESCE(category_ru, 'обед'), ingredients_ru = COALESCE(ingredients_ru, '["Кабачки - 2 шт.","Говяжий фарш - 150 г","Лук - 1 шт.","Помидор - 1 шт.","Сыр - 30 г"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разрежьте овощи и удалите сердцевину","Приготовьте мясо с луком и помидором","Наполните овощи начинкой","Запекайте при 180°C 25-30 минут","Посыпьте сыром"]'::jsonb) WHERE id = '2f2b9ad9-7480-4118-bad9-8cd23415bda5';
