UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Теплый салат с зеленой чечевицей'), description_ru = COALESCE(description_ru, 'Источник фолиевой кислоты и клетчатки, легкий вариант ужина'), category_ru = COALESCE(category_ru, 'ужин'), ingredients_ru = COALESCE(ingredients_ru, '["Зеленая чечевица - половина стакана","Морковь - 1 шт.","Шпинат - 1 горсть","Лимонный сок","Оливковое масло"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Сварите чечевицу","Добавьте морковь и шпинат","Перемешайте с соусом из лимонного сока и масла"]'::jsonb) WHERE id = '9194dcd7-0593-42ea-be60-36f52bfc96b4';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Десерт из айвы в духовке'), description_ru = COALESCE(description_ru, 'Айва — один из самых эффективных фруктов для облегчения тошноты'), category_ru = COALESCE(category_ru, 'полезные_десерты'), ingredients_ru = COALESCE(ingredients_ru, '["Айва - 2 шт.","Яблоко - 1 шт.","Палочка корицы - 1 шт.","Гвоздика - 3 шт.","Мед, грецкие орехи"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разрежьте айву и наполните ее тертым яблоком","Добавьте корицу и гвоздику","Запекайте при 180°C 50 минут","Полейте медом"]'::jsonb) WHERE id = '71de5174-6da5-4ea3-85bb-14cde99315cd';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Смузи «Миндальное наслаждение»'), description_ru = COALESCE(description_ru, 'Естественная сладость миндального молока и фиников. Богат омега-3 и кальцием, способствует повышению жирности грудного молока.'), category_ru = COALESCE(category_ru, 'полезные_напитки'), ingredients_ru = COALESCE(ingredients_ru, '["Миндаль: 1 горсть (замоченный с вечера, очищенный от кожицы)","Молоко: 1 стакан","Банан: 1 шт.","Мед: 1 чайная ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Замочите миндаль в воде с вечера, а утром очистите от кожицы","Взбейте миндаль с молоком в блендере до однородности","Добавьте банан и мед и снова взбейте в блендере","Пейте охлажденным или комнатной температуры","1 стакан каждый день способствует увеличению количества грудного молока"]'::jsonb) WHERE id = 'a816a450-3561-451f-b7de-9d70662f2972';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Чиа-пудинг с фруктами'), description_ru = COALESCE(description_ru, 'Богат омега-3 жирными кислотами. Идеально подходит тем, кто страдает запорами.'), category_ru = COALESCE(category_ru, 'завтрак'), ingredients_ru = COALESCE(ingredients_ru, '["Семена чиа - 2 столовые ложки","Молоко - 1 стакан","Мед - 1 чайная ложка","Свежие фрукты"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смешайте чиа, мед и молоко","Оставьте в холодильнике на 4 часа","Добавьте фрукты и подавайте"]'::jsonb) WHERE id = 'a447ee30-24f2-4732-9007-6f2676858ba8';
