UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Печенье «Млечный путь»'), description_ru = COALESCE(description_ru, 'Полезная версия популярного во всём мире печенья для лактации Lactation Cookies. Овёс и семена льна способствуют повышению уровня пролактина.'), category_ru = COALESCE(category_ru, 'полезные_сладости'), ingredients_ru = COALESCE(ingredients_ru, '["Овёс: 1.5 стакана","Сливочное масло: 50 г","Мёд: 3 столовые ложки","Яйцо: 1 шт.","Семена льна: 2 столовые ложки","Шоколадные капли: по желанию"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Растопите сливочное масло и взбейте его с мёдом и яйцом","Добавьте овёс и семена льна, затем перемешайте","По желанию добавьте шоколадные капли","Ложкой выложите на бумагу круглые заготовки","Выпекайте при 175°C 12-15 минут — ешьте по 2-3 штуки в день"]'::jsonb) WHERE id = 'f09a3c1e-ec4c-4eb2-b2d1-b699bce46612';
