UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Зелёный детокс-эликсир'), description_ru = COALESCE(description_ru, 'Супернапиток «зелёный сок», способствующий очищению печени и кожи и обновлению клеток.

