UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Гратен из баклажанов'), description_ru = COALESCE(description_ru, 'Диетическая версия знаменитого итальянского блюда "Пармиджана", приготовленная без обжаривания.

