UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Хрустящие тако-чашечки (3 года+)'), description_ru = COALESCE(description_ru, 'Мексиканское блюдо с высоким содержанием белка в хрустящих чашечках из лаваша.

