Польза: шпинат и оливковое масло поддерживают работу кишечника и естественные процессы очищения организма.'), category_ru = COALESCE(category_ru, 'завтрак'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Молодой шпинат или салатные листья: 1-2 горсти","Яйцо вкрутую: 1 штука","Грецкие орехи: 2-3 штуки","Оливковое масло и лимонный сок.","Творог: 2 столовые ложки."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Выложите шпинат в миску. Добавьте нарезанное яйцо, творог и грецкие орехи. Полейте оливковым маслом и лимонным соком."]'::jsonb) WHERE id = 'b7b9eff5-fed2-499e-b5d9-5c57fb32426f';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Золотые зёрна — плов из булгура'), description_ru = COALESCE(description_ru, 'Сочетание булгура и чечевицы. Богато витаминами группы B и питательными веществами, необходимыми в период грудного вскармливания.'), category_ru = COALESCE(category_ru, 'обед'), ingredients_ru = COALESCE(ingredients_ru, '["Булгур: 1 стакан","Зелёная чечевица: половина стакана (отварная)","Лук: 1 штука","Сливочное масло: 1 столовая ложка","Вода: 2 стакана"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обжарьте лук на сливочном масле до золотистого цвета","Добавьте промытый булгур и обжаривайте 1-2 минуты","Добавьте заранее отваренную чечевицу","Влейте 2 стакана воды и доведите до кипения","Готовьте под крышкой на слабом огне до полного впитывания воды (15-20 минут)"]'::jsonb) WHERE id = 'dcd85da7-ccb3-4272-a895-942bd99de63b';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Смузи «Дзен-баланс»'), description_ru = COALESCE(description_ru, 'Успокаивающий напиток для тех, кого беспокоит изжога'), category_ru = COALESCE(category_ru, 'полезные_напитки'), ingredients_ru = COALESCE(ingredients_ru, '["Овсяные хлопья - 2 столовые ложки","Банан - 1 штука","Молоко - 1 стакан","Мёд - 1 чайная ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Слегка проварите овсяные хлопья в молоке","Смешайте в блендере с бананом и мёдом"]'::jsonb) WHERE id = 'db9dd331-557e-46cd-9d2b-a47d4771ad41';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Cumin Comfort — чечевичный суп'), description_ru = COALESCE(description_ru, 'Суп, который помогает уменьшить газообразование у мамы и малыша. Зира традиционно используется для поддержки лактации и облегчения колик.'), category_ru = COALESCE(category_ru, 'грудное_вскармливание'), tags_ru = COALESCE(tags_ru, ARRAY['послеродовой_период', 'поддержка_лактации']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Красная чечевица: 1 стакан","Лук: 1 штука","Картофель: 1 штука","Зира (кумин): 1 чайная ложка (с горкой)","Сливочное масло: 1 столовая ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Нарежьте чечевицу, лук и картофель и отварите в воде","Когда ингредиенты станут мягкими, измельчите их блендером","Отдельно прогрейте зиру (кумин) в сливочном масле до появления аромата","Полейте суп горячим маслом с зирой","Пейте горячим — для поддержки лактации и уменьшения колик"]'::jsonb) WHERE id = '56b6eb44-1b68-4703-8191-5abf175ce6b4';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пробиотическое парфе'), description_ru = COALESCE(description_ru, 'Источник кальция и пробиотиков для здоровья кишечника — «второго мозга».

Польза: здоровая микрофлора кишечника важна для поддержания иммунитета и психологического благополучия женщины.'), category_ru = COALESCE(category_ru, 'завтрак'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Густой процеженный йогурт (или греческий йогурт): 1 стакан","Гранола без сахара (или смесь обжаренных овсяных хлопьев и орехов): 3 столовые ложки","Свежие фрукты (киви, персик или клубника): Нарезанные"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["В высокий стакан слоями выложите сначала половину йогурта, затем фрукты и гранолу. Сверху добавьте оставшийся йогурт и посыпьте небольшим количеством гранолы."]'::jsonb) WHERE id = '06ed0fa8-cbd9-44a6-9ddc-7e7b1fe1e84d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Golden Cream — хумус'), description_ru = COALESCE(description_ru, 'Вкусное сочетание нута и тахини, традиционно используемых для поддержки лактации. Источник растительного белка и кальция.'), category_ru = COALESCE(category_ru, 'обед'), ingredients_ru = COALESCE(ingredients_ru, '["Нут: 1 стакан (отварной)","Тахини (кунжутная паста): 2 столовые ложки","Лимонный сок: 1 столовая ложка","Чеснок: 1 зубчик","Оливковое масло: 2 столовые ложки"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Заранее замочите нут и отварите до мягкости","Поместите в блендер нут, тахини, лимонный сок и чеснок","Измельчите до однородной кремовой консистенции","При необходимости добавьте немного воды, в которой варился нут","Полейте оливковым маслом и подавайте с хлебом"]'::jsonb) WHERE id = '9448c07e-1f48-40e0-a861-ab4dcd62db5b';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Белая рыба с ароматом цитрусов'), description_ru = COALESCE(description_ru, 'Ароматное и нежное блюдо из морской рыбы, которое совсем не нагружает желудок.

Польза: белая рыба (сибас, судак) — источник легкоусвояемого чистого белка и йода, необходимого для здоровья щитовидной железы. Лимон помогает усвоению железа.'), category_ru = COALESCE(category_ru, 'ужин'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Филе белой рыбы: 150-200 г","Лимон и апельсин: по 2 ломтика","Свежий тимьян или розмарин: 1-2 веточки","Оливковое масло, соль, чёрный перец."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Выложите очищенную рыбу на пергаментную бумагу. Посолите, поперчите и сбрызните маслом. Сверху положите ломтики цитрусов и зелень. Заверните бумагу в виде пакета и запекайте 20 минут при 180 градусах. Подавайте с большой порцией зелёного салата."]'::jsonb) WHERE id = '69335e75-4e74-4b38-bb31-495c4674ceb3';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тропический оазис'), description_ru = COALESCE(description_ru, 'Чистый освежающий напиток, который помогает восстановить водно-электролитный баланс и уменьшить отёки.

Польза: кокосовая вода — натуральный спортивный напиток, богатый калием. Огурец способствует увлажнению кожи и поддерживает естественное очищение организма изнутри.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), ingredients_ru = COALESCE(ingredients_ru, '["Натуральная кокосовая вода: 1 стакан","Огурец: ломтики, нарезанные тонкими лентами","Свежая мята и сок лайма."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Сложите все ингредиенты в графин или большой стакан и оставьте в холодильнике на 30 минут, чтобы вкусы соединились. Пейте охлаждённым."]'::jsonb) WHERE id = '59177852-56ab-4ae0-9965-367e9142cf8e';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Салат с авокадо и курицей'), description_ru = COALESCE(description_ru, 'Низкоуглеводное блюдо, которое надолго насыщает и питает мышцы.

Польза: сочетание сытного белка (курица) и полезных жиров (авокадо) помогает предотвратить приступы тяги к сладкому.'), category_ru = COALESCE(category_ru, 'обед'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Куриная грудка: 150 г (приготовленная на гриле или обжаренная на сковороде)","Авокадо: половина (нарезанная ломтиками)","Молодой шпинат или салатные листья: 2 горсти","Помидоры черри: 5-6 шт.","Лимонный сок, оливковое масло."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Нарежьте курицу длинными ломтиками. Выложите зелень, помидоры и авокадо на большую тарелку, сверху добавьте ломтики курицы. Заправьте лимонным соком и оливковым маслом."]'::jsonb) WHERE id = '0ad5770d-c00e-4aaf-a326-ab7ca620f797';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тост с авокадо и яйцом (1 год+)'), description_ru = COALESCE(description_ru, 'Любимое блюдо годовалых малышей, которые обожают есть самостоятельно.

Польза: авокадо богат полезными жирами, а яйцо обеспечивает организм незаменимыми аминокислотами.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Цельнозерновой хлеб: 1 ломтик (без корочки, поджаренный)","Авокадо: четверть (тщательно размятая)","Яйцо: 1 шт. (сваренное вкрутую и натёртое)"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Намажьте размятый авокадо на поджаренный хлеб. Посыпьте сверху тёртым яйцом. Нарежьте длинными полосками, которые ребёнку будет удобно держать в руке."]'::jsonb) WHERE id = '3d1a500a-b203-4052-b1f2-91a4407a4e3c';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Макароны со шпинатом (4 года+)'), description_ru = COALESCE(description_ru, 'Волшебный сырный соус, богатый железом и привлекающий детей своим ярким зелёным цветом.

Польза: шпинат и грецкие орехи поддерживают развитие мозга ребёнка и обеспечивают его энергией.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Цельнозерновые или цветные безглютеновые макароны: 1 стакан","Шпинат: 1 большая горсть","Ядра грецких орехов: 2 шт.","Сливочный сыр или оливковое масло: 1 столовая ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите макароны. Измельчите шпинат, грецкие орехи и сыр (или масло) в блендере до получения полностью однородного ярко-зелёного крема. Смешайте горячие макароны с этим соусом и подавайте."]'::jsonb) WHERE id = 'c842f7bd-4741-487b-b42c-981f40c245be';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Котлетки «Суперсила» (2 года+)'), description_ru = COALESCE(description_ru, 'Запечённые котлетки с сюрпризом внутри, которые с удовольствием съедят даже дети, не любящие мясо.

Польза: чистый куриный белок и железо из брокколи в одном блюде. Благодаря запеканию, а не жарке, они не нагружают желудок.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Куриный фарш: 200 г","Брокколи: 3-4 соцветия (измельчённые в блендере очень мелко, почти в порошок)","Лук: очень маленький кусочек (натёртый)","Панировочные сухари: 1 столовая ложка","Оливковое масло и немного соли."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Тщательно вымесите все ингредиенты в миске.","Сформируйте котлетки размером чуть меньше грецкого ореха, чтобы ребёнку было удобно брать их рукой и есть.","Выложите на застеленный пергаментной бумагой противень и запекайте 20-25 минут при 180 градусах."]'::jsonb) WHERE id = 'ce232b23-613e-4e89-87ba-f0def071b9bc';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Ягодная магия с чиа'), description_ru = COALESCE(description_ru, 'Освежающий перекус — настоящая антиоксидантная бомба, увлажняющая кожу изнутри.'), category_ru = COALESCE(category_ru, 'завтрак'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Семена чиа: 3 столовые ложки","Миндальное молоко (или кокосовое молоко): 1 стакан","Свежая малина или голубика: 1 горсть","Мёд или кленовый сироп: 1 чайная ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["С вечера тщательно смешайте в миске семена чиа, молоко и мёд. Через 10 минут перемешайте ещё раз, чтобы не образовались комочки. Оставьте в холодильнике до утра. Утром украсьте свежими ягодами и подавайте."]'::jsonb) WHERE id = '76ceddd0-3762-4c0e-938c-757205264083';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Салат со свёклой и сыром'), description_ru = COALESCE(description_ru, 'Лёгкий обед, поддерживающий кровообращение и радующий глаз ярким цветом.

Польза: свёкла считается одним из лучших овощей для поддержки естественной работы печени, а козий сыр или творог — источник легкоусвояемого кальция.'), category_ru = COALESCE(category_ru, 'обед'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Свёкла: 1 среднего размера (запечённая или отварная, нарезанная кубиками)","Козий сыр (или рассольный сыр/творог): 2 столовые ложки","Ядра грецких орехов: 1 горсть","Листья рукколы.","Бальзамический уксус и оливковое масло."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Выложите на листья рукколы нарезанную свёклу, сыр и грецкие орехи. Полейте смесью бальзамического уксуса и оливкового масла."]'::jsonb) WHERE id = 'db6223cf-fd40-4b31-9334-3aa607532faa';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тост с авокадо'), description_ru = COALESCE(description_ru, 'Самое вкусное сочетание полезных жиров и качественного белка.

Польза: Авокадо содержит полезные жиры, важные для женской гормональной системы, а яйцо — полноценный белок, который помогает поддерживать мышцы.'), category_ru = COALESCE(category_ru, 'завтрак'), tags_ru = COALESCE(tags_ru, ARRAY['общие']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Цельнозерновой или ржаной хлеб: 1-2 больших ломтика","Авокадо: Половина (спелого)","Яйцо: 1-2 шт. (приготовленных в воде — пашот или припущенных)","Лимонный сок, соль, красный перец хлопьями."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Поджарьте хлеб. Разомните авокадо вилкой, смешайте с лимонным соком и солью, затем намажьте на хлеб. Сверху выложите приготовленное яйцо и посыпьте хлопьями красного перца."]'::jsonb) WHERE id = 'be15d84a-f891-40e8-bcea-25a7ea3f5e77';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Панкейки со шпинатом (1 год+)'), description_ru = COALESCE(description_ru, 'Мягкие и вкусные разноцветные облачка без сахара для завтрака.

Польза: Прекрасное сочетание шпината и банана. Богаты железом и калием.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Молодой шпинат: 1 горсть","Банан: 1 шт. (спелый)","Яйцо: 1 шт.","Мука (цельнозерновая или овсяная): 2 столовые ложки"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Измельчите шпинат, банан и яйцо в блендере до получения полностью однородной зелёной массы. Добавьте муку и перемешайте. Выкладывайте тесто ложкой на сковороду без масла и обжаривайте с обеих сторон."]'::jsonb) WHERE id = 'e3b32abb-4f90-4796-9370-d8e31b9a5d8e';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Лодочки из батата (4 года+)'), description_ru = COALESCE(description_ru, 'Красочные витаминные лодочки в форме корабликов.

Польза: Батат содержит витамин A, полезный для зрения. Кукуруза и зелёный горошек придают блюду интересную текстуру.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Батат: 2 шт. (разрезанных пополам и запечённых в духовке)","Зелёный горошек и кукуруза: По 1 столовой ложке (отварных)","Разобранное на волокна куриное мясо или фарш: 2 столовые ложки","Сыр (для паруса)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Слегка выньте мякоть из запечённого батата и разомните её в пюре. Смешайте с горошком, кукурузой и мясом, затем снова наполните половинки батата. Вставьте сверху зубочистку с треугольным кусочком сыра в виде паруса."]'::jsonb) WHERE id = 'd55a1489-0c64-4fd1-9c95-61ccad0e27bf';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Какао с апельсином'), description_ru = COALESCE(description_ru, 'Витамин C из апельсина помогает усваивать железо, содержащееся в какао. Придаёт коже сияние.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['общие']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["1 столовая ложка какао, 1 стакан миндального молока, 1 столовая ложка свежевыжатого апельсинового сока (или натёртой апельсиновой цедры), 1 чайная ложка пекмеза."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Растворите какао в горячем миндальном молоке. Сняв с огня, добавьте апельсиновый сок и пекмез."]'::jsonb) WHERE id = 'c4928087-d44e-49b9-b047-6872459c8c34';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Кабачки с индейкой'), description_ru = COALESCE(description_ru, 'Аппетитные белковые «лодочки» без теста и хлеба.

Польза: Содержат очень мало углеводов. Аминокислота «триптофан», содержащаяся в мясе индейки, способствует выработке мелатонина — гормона сна, помогая глубокому и спокойному засыпанию.'), category_ru = COALESCE(category_ru, 'ужин'), tags_ru = COALESCE(tags_ru, ARRAY['общие']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Кабачки: 2 среднего размера (разрезанных вдоль, с удалённой мякотью)","Фарш из индейки (или нежирной говядины): 150 qr","Помидор: 1 шт. (натёртый)","Моцарелла или голландский сыр: 30 qr (натёртого)","Лук, чеснок, тимьян."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обжарьте фарш с луком, чесноком и помидором на сковороде до полуготовности. Наполните кабачковые лодочки фаршем и запекайте в духовке при 180 градусах, пока кабачки не станут мягкими (примерно 25 минут). За 5 минут до готовности посыпьте сверху сыром."]'::jsonb) WHERE id = 'f34874ad-c7fb-4bad-9d1d-814135cad038';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Лосось и брокколи
(9 месяцев+)'), description_ru = COALESCE(description_ru, 'Первое знакомство с морепродуктами, богатыми жирными кислотами Омега-3, необходимыми для формирования клеток мозга.

Польза: Лосось важен для развития мозга и нервной системы. Брокколи служит источником кальция и витамина C.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Лосось (филе): 30 qr (полностью без костей)","Брокколи: 2-3 соцветия","Оливковое масло: Несколько капель."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Хорошо приготовьте рыбу и брокколи на пару (или в небольшом количестве воды). Разбирая рыбу вилкой, ещё раз внимательно проверьте, не осталось ли костей. Разомните вместе с брокколи и добавьте несколько капель оливкового масла."]'::jsonb) WHERE id = 'd3ad67eb-6c19-4eee-9f9a-b784483c1a16';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Рис с овощами (4 года+)'), description_ru = COALESCE(description_ru, 'Праздничный рис с разноцветными овощами.

Польза: Сытный обед, в котором в одной кастрюле сочетаются углеводы, витамины и клетчатка.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Рис басмати или длиннозёрный рис: 1 стакан","Морковь, зелёный горошек, сладкий красный перец, кукуруза: По 2 столовые ложки (нарезанных мелкими кубиками)","Сливочное масло и куриный бульон."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Слегка обжарьте овощи на сливочном масле. Добавьте промытый рис и бульон, готовьте до полного впитывания жидкости, пока рис не станет рассыпчатым."]'::jsonb) WHERE id = 'f04550c5-0fdb-4ab9-8b7b-831a4d2f5e5a';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Стейк из цветной капусты в духовке'), description_ru = COALESCE(description_ru, 'Самый известный «заменитель мяса» в мире веганского и здорового питания. Внешне напоминает стейк.

Польза: Содержит очень мало калорий и много клетчатки. При запекании натуральные сахара капусты карамелизуются, создавая великолепный вкус.'), category_ru = COALESCE(category_ru, 'общие'), tags_ru = COALESCE(tags_ru, ARRAY['общие']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Цветная капуста: 1 целый кочан (очень большой)","Оливковое масло: 2 столовые ложки","Сушёный чеснок, сладкий красный молотый перец (паприка), морская соль, чёрный перец."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Вымойте цветную капусту целиком и нарежьте из середины цельные ломтики-«стейки» толщиной 2 сантиметра. Выложите на противень и смажьте с обеих сторон оливковым маслом со смесью специй. Запекайте при 200 градусах до румяной корочки с обеих сторон (примерно 25-30 минут)."]'::jsonb) WHERE id = 'dbb5731f-3844-4a55-a0b0-63c083018f90';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Яйца-лодочки (3 года+)'), description_ru = COALESCE(description_ru, 'Весёлая закуска в форме «кораблика» для детей, которые не любят яичный желток.

Польза: Холин, содержащийся в яичном желтке, — один из важнейших элементов для быстро развивающегося мозга и памяти трёхлетнего ребёнка.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Яйца, сваренные вкрутую: 2 штуки","Йогурт: 1 чайная ложка","Очень мелко нарезанный разноцветный перец (для «сокровищ»)","Сыр: тонкие треугольные ломтики (для паруса) и зубочистка."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разрежьте яйца вдоль пополам. Выньте желтки, разомните их с йогуртом, добавьте кусочки разноцветного перца («сокровища») и снова наполните белки. Нанижите треугольный ломтик сыра на зубочистку и вставьте в яйцо как «парус» (не забудьте вынуть зубочистку перед едой!)."]'::jsonb) WHERE id = '38175de9-042b-4fc9-8a58-cdff56307d6d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Фаршированные грибы портобелло'), description_ru = COALESCE(description_ru, 'Восхитительные «шляпки», которые обладают мясистой текстурой и насыщенным вкусом, хотя не содержат красного мяса.

Польза: Грибы портобелло богаты селеном — минералом, который защищает кожу от преждевременного старения. Они легко перевариваются и не перегружают желудок.'), category_ru = COALESCE(category_ru, 'ужин'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Грибы портобелло: 2 большие штуки (ножки удалены, шляпки очищены изнутри)","Шпинат: 1 горсть (нарезанный)","Киноа (или булгур): 2 столовые ложки (в готовом виде)","Фета (или белый сыр): 1 столовая ложка"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Наполните грибы смесью киноа, шпината и сыра. Выложите в форму для запекания и слегка сбрызните оливковым маслом. Запекайте при 180 градусах, пока грибы не станут мягкими."]'::jsonb) WHERE id = 'fef93b73-64a7-48d4-94bf-fe08f3ed1adc';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Рубиновое печенье'), description_ru = COALESCE(description_ru, 'Безглютеновое печенье без муки с джемом и углублением в центре — прекрасное дополнение к чаепитию.

Польза: Миндальная мука насыщает кожу витамином E, а домашний «джем» из чиа помогает восполнить потребность в Омега-3.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Миндальная мука: 1.5 стакана","Мёд или сироп агавы: 3 столовые ложки","Кокосовое масло: 2 столовые ложки (растопленное)","Свежая малина и 1 столовая ложка семян чиа (для джема)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разомните малину вилкой и смешайте с чиа (оставьте на 15 мин., чтобы смесь загустела). Замесите тесто из миндальной муки, масла и мёда и сформируйте небольшие шарики. Сделайте пальцем углубление в центре каждого и выпекайте в духовке при 160 градусах в течение 10 мин. Достаньте печенье и наполните углубления малиновым джемом с чиа."]'::jsonb) WHERE id = '6b9ff319-0e3b-432c-ae21-5efca3c9d50d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пюре из свёклы и яблока
(7 месяцев+)'), description_ru = COALESCE(description_ru, 'Сладкое пюре для укрепления иммунитета, которое подарит щёчкам вашего малыша румянец.

Польза: Свёкла считается одним из самых действенных натуральных продуктов при анемии. Яблоко смягчает землистый вкус свёклы.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Свёкла: 1 небольшая штука","Яблоко: половина"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите свёклу в кожуре или запеките в духовке (чтобы сохранить витамины). Затем очистите и измельчите вместе с яблоком в блендере до однородного пюре. Следите, чтобы пюре не попало на одежду!"]'::jsonb) WHERE id = '55df2691-7b63-4f38-bfb6-d946010b6903';